stringFiles[105].addEntry("s_7e6edae", "This will cost %DI points of prestige.  Do you wish to spend the points and enter?");
stringFiles[105].addEntry("s_993453d7", "Imperials are not welcome here.");
stringFiles[105].addEntry("s_a785faa6", "Which side would you like to support?");
stringFiles[105].addEntry("s_a99b5897", "This area of Deep Space has been closed by order of the Empire.  The only way to get in is to pose as either an Imperial yourself, or to use the Rebel Alliance's hyperspace route.  Be warned though, whichever route you choose, you will be treated as an enemy by the other side!");
stringFiles[105].addEntry("s_c4588d4d", "I want to go to Kessel");
