stringFiles[106] = new StringFile("conversation/battlefield_entry_station_rebel");
stringFiles[106].addEntry("do_not_edit", "The English version of this file (battlefield_entry_station_rebel) is automatically generated by the SwgConversationEditor.");
stringFiles[106].addEntry("s_0", "");
stringFiles[106].addEntry("s_17456755", "Sign up with the Rebel Alliance and we'll talk.");
