stringFiles[384] = new StringFile("conversation/quest_ship_rebel");
stringFiles[384].addEntry("do_not_edit", "The English version of this file (quest_ship_rebel) is automatically generated by the SwgConversationEditor.");
stringFiles[384].addEntry("s_0", "");
stringFiles[384].addEntry("s_13e02273", "Z-95 Headhunter");
stringFiles[384].addEntry("s_159911f5", "Tell me more.");
stringFiles[384].addEntry("s_248053ce", "I want to join the Alliance.");
stringFiles[384].addEntry("s_2bf47aa", "Excellent. The Force be with you.");
stringFiles[384].addEntry("s_3af0ea69", "Any news to speak of?");
stringFiles[384].addEntry("s_40daf62", "Then, keep your mouth shut about the operation. Stay close. Let me know when you're ready to fly.");
stringFiles[384].addEntry("s_4c695dbd", "No.");
stringFiles[384].addEntry("s_5e865634", "Done. Here's your starship keycard. Good luck.");
stringFiles[384].addEntry("s_6d4ad708", "Takes a lot of guts to fly for the Alliance, my friend. Do you expect me to believe you're ready... just like that?");
stringFiles[384].addEntry("s_7971c070", "IMPERIAL SECRET DRY DOCK");
stringFiles[384].addEntry("s_869babb1", "QUEST 02 SUMMARY. WANT IT?");
stringFiles[384].addEntry("s_8c8023e8", "QUEST 03 SUMMARY. WANT IT?");
stringFiles[384].addEntry("s_8c832f88", "I am ready for my ship assignment.");
stringFiles[384].addEntry("s_8d00c343", "NPC INFO");
stringFiles[384].addEntry("s_8e631419", "Y-Wing");
stringFiles[384].addEntry("s_954b1961", "X-Wing");
stringFiles[384].addEntry("s_97b1a69", "PLAYER IS ON MISSION.");
stringFiles[384].addEntry("s_98b7335a", "QUEST 01 SUMMARY. WANT IT?");
stringFiles[384].addEntry("s_a4c56130", "BASIC LOCATION INFO.");
stringFiles[384].addEntry("s_a560e84c", "I am looking for work.");
stringFiles[384].addEntry("s_b1655983", "QUEST INFO.");
stringFiles[384].addEntry("s_b4adb823", "MISSION IS COMPLETE. HOW DID IT GO?");
stringFiles[384].addEntry("s_c478ce87", "Tell me about yourself.");
stringFiles[384].addEntry("s_cc1aa266", "B-Wing");
stringFiles[384].addEntry("s_d70dba34", "Yes.");
stringFiles[384].addEntry("s_dde9987c", "GREETING.");
stringFiles[384].addEntry("s_e162b5ee", "A-Wing");
stringFiles[384].addEntry("s_e45f3234", "Greetings, Pilot.");
stringFiles[384].addEntry("s_eafe8f5e", "SELONIAN SEPARATISTS VS REBEL SUPPLY CNV");
stringFiles[384].addEntry("s_ee9092a0", "What does your mission require?");
