stringFiles[446].addEntry("s_ebce22a9", "NO, wait. Let me think a moment longer.");
stringFiles[446].addEntry("s_edb238bc", "Go on.");
stringFiles[446].addEntry("s_f51b07ff", "What kind of questions?");
