stringFiles[481] = new StringFile("craft_droid_ingredients_d");
stringFiles[481].addEntry("advanced_droid_frame", "This advanced droid frame is sturdier than the standard frame.");
stringFiles[481].addEntry("armor_module_1", "This armor module is used to help protect a droid from bangs, falls, and weak blaster fire.");
stringFiles[481].addEntry("armor_module_2", "This armor module is used to help protect a droid from bangs, falls, and weak blaster fire.");
stringFiles[481].addEntry("armor_module_3", "This armor module is used to help protect a droid from bangs, falls, and weak blaster fire.");
