stringFiles[737] = new StringFile("lord_hethrir_1");
stringFiles[737].addEntry("informant1", "You must be who Lord Hethrir sent to talk to me.  Listen, I have discovered the whereabouts of a fringe group that has been selling explosives to radicals!");
stringFiles[737].addEntry("informant1_reply1", "Tell me.");
stringFiles[737].addEntry("informant2", "What are you trying to do, blow my cover?");
stringFiles[737].addEntry("informant2_reply1", "Of course not.  I'll go now.");
stringFiles[737].addEntry("informant3", "They've established a small camp.  I load the coordinates into your datapad.");
stringFiles[737].addEntry("lord1", "Speak to my contact outside of Moenia and track down the insurgents.");
stringFiles[737].addEntry("lord1_reply1", "Will do.");
stringFiles[737].addEntry("lord1_reply2", "No time for that now.");
stringFiles[737].addEntry("lord2", "Hurry up.  The safety of the Imperial Citizens depends on your quick action.");
stringFiles[737].addEntry("lord3", "Finish whatever business is delaying you immediately, and then speak to me again.");

