stringFiles[828].addEntry("probe_droid_launch_prep", "Probe Droid request received. Prepping capsule for launch. ETA 20 seconds. ");
stringFiles[828].addEntry("probe_droid_program", "Transmit Biological Signature");
stringFiles[828].addEntry("probe_droid_takeoff", "Target data received. Commencing interplanetary search pattern. ");
stringFiles[828].addEntry("probe_droid_too_many", "You cannot launch another probe droid. ");
stringFiles[828].addEntry("probe_droid_track_target", "Find and Track Target");
