stringFiles[828].addEntry("target_located_dantooine", "Your target has been located on Dantooine.");
stringFiles[828].addEntry("target_located_dathomir", "Your target has been located on Dathomir.");
stringFiles[828].addEntry("target_located_dungeon1", "Your target is somewhere out in space.  You'll have to try again once he has returned to a planet.");
stringFiles[828].addEntry("target_located_endor", "Your target has been located on Endor.");
stringFiles[828].addEntry("target_located_lok", "Your target has been located on Lok.");
stringFiles[828].addEntry("target_located_naboo", "Your target has been located on Naboo.");
stringFiles[828].addEntry("target_located_rori", "Your target has been located on Rori.");
stringFiles[828].addEntry("target_located_taanab", "Your target has been located on Taanab.");
stringFiles[828].addEntry("target_located_talus", "Your target has been located on Talus.");
