stringFiles[942] = new StringFile("mob/base_npc_convo");
stringFiles[942].addEntry("player_job_accept", "Sure, I'll take your job.");
stringFiles[942].addEntry("player_job_refuse", "I think I'll pass on this one.");
stringFiles[942].addEntry("player_job_request", "Do you need anything done?");
stringFiles[942].addEntry("thug_npc_do_job", "Then get to work!");
stringFiles[942].addEntry("thug_npc_go_home", "I knew you were a waste of my time.");
stringFiles[942].addEntry("thug_npc_greet_1", "What do you want?");
stringFiles[942].addEntry("thug_npc_greet_2", "Yeah?  What?!?");
stringFiles[942].addEntry("thug_npc_greet_3", "Make this quick, ok?");
stringFiles[942].addEntry("thug_npc_job_offer_1", "I got work.  If you don't mind getting your hands dirty you can have it.  Want it?");
stringFiles[942].addEntry("thug_npc_job_offer_2", "There's plenty to do if you're willing to bend a few laws...");
stringFiles[942].addEntry("thug_npc_job_offer_3", "I don't know if I trust you, but I got something I need done if you're willing.");
stringFiles[942].addEntry("thug_npc_response_1_1", "Whoever pays the most.");
stringFiles[942].addEntry("thug_npc_response_1_2", "Who says I'm being hostile?");
stringFiles[942].addEntry("thug_npc_response_1_3", "What's it to you?");
stringFiles[942].addEntry("thug_npc_response_2_1", "Answering questions like that can get you killed.");
stringFiles[942].addEntry("thug_npc_response_2_2", "Do I care?  No.  Go away.");
stringFiles[942].addEntry("thug_npc_response_2_3", "Well don't.");
stringFiles[942].addEntry("thug_npc_response_3_1", "Didn't everyone?");
stringFiles[942].addEntry("thug_npc_response_3_2", "Very.");
stringFiles[942].addEntry("thug_npc_response_3_3", "I'll forget this whole thing ever happened");
stringFiles[942].addEntry("thug_player_line_1_1", "Who do you work for?");
stringFiles[942].addEntry("thug_player_line_1_2", "Why are you being so hostile?");
stringFiles[942].addEntry("thug_player_line_1_3", "You got somewhere to be?");
stringFiles[942].addEntry("thug_player_line_2_1", "Ever work for Valarian?");
stringFiles[942].addEntry("thug_player_line_2_2", "Um...that was me.");
stringFiles[942].addEntry("thug_player_line_2_3", "I'm just asking is all.");
stringFiles[942].addEntry("thug_player_line_3_1", "Ever work for Jabba?");
stringFiles[942].addEntry("thug_player_line_3_2", "You're rude aren't you?");
stringFiles[942].addEntry("thug_player_line_3_3", "Forget I asked.");

