stringFiles[952].addEntry("destroy_mission_complete", "You have completed your sample Destroy Mission");
stringFiles[952].addEntry("destroy_mission_start", "Follow the waypoint to target and destroy it.");
stringFiles[952].addEntry("gig_mission_arrival", "You've arrived at the cantina, go inside and start your performance.");
stringFiles[952].addEntry("gig_mission_complete", "You have completed your sample Gig Mission.");
stringFiles[952].addEntry("gig_mission_dance_start", "Follow the waypoint to your local cantina, go inside and dance for 2 minutes.");
stringFiles[952].addEntry("gig_mission_music_start", "Follow the waypoint to your local cantina, go inside and play a song for 2 minutes.");
stringFiles[952].addEntry("harvest_mission_complete", "You have sucessfully harvested resources from your target.");
stringFiles[952].addEntry("harvest_mission_start", "Follow the waypoint to your target and kill it.");
stringFiles[952].addEntry("harvest_mission_target_dead", "Now that your target is dead, use your skills to harvest the natural resources from it.");
stringFiles[952].addEntry("heal_mission_arrival", "You have found your patient, start healing %OT as soon as possible.");
stringFiles[952].addEntry("heal_mission_complete", "You have sucessfully healed your patient.");
