stringFiles[952].addEntry("heal_mission_use", "Use Medicine");
stringFiles[952].addEntry("heal_mission_wrong_target", "This is not the correct patient.");
stringFiles[952].addEntry("survey_mission_complete", "You have completed your sample Survey Mission.");
