stringFiles[957] = new StringFile("npc_convo");
stringFiles[957].addEntry("hutt_cry_for_help_1", "Help!  I need assistance!");
stringFiles[957].addEntry("hutt_cry_warning_1", "Watch it!");
stringFiles[957].addEntry("hutt_dislike_farewell_1", "If you come back again I'll probably kill you.");
stringFiles[957].addEntry("hutt_dislike_greeting_1", "I don't have time for your petty troubles.");
stringFiles[957].addEntry("hutt_dislike_see_attack_1", "Haha!  That's what you get.");
stringFiles[957].addEntry("hutt_dislike_see_death", "Too bad you can't bring him back and kill him again.");
stringFiles[957].addEntry("hutt_like_farewell_1", "Stay out of trouble, friend.");
stringFiles[957].addEntry("hutt_like_greeting_1", "Good to see you.  How are things?");
stringFiles[957].addEntry("hutt_like_see_attack_1", "Keep your head down, I'll try to help!");
stringFiles[957].addEntry("hutt_like_see_death_1", "Don't think we're gonna let you get away with that.");
stringFiles[957].addEntry("hutt_loot_1", "This is good stuff.");
stringFiles[957].addEntry("hutt_mission_accepted_1", "Good.  Welcome to the team.");
stringFiles[957].addEntry("hutt_mission_declined_1", "Well, not everyone's cut out for the life.");
stringFiles[957].addEntry("hutt_neutral_farewell_1", "See you.");
stringFiles[957].addEntry("hutt_neutral_greeting_1", "What can you do for me?");
