stringFiles[957].addEntry("imperial_dislike_see_attack_1", "Excellent shot sir.");
stringFiles[957].addEntry("imperial_dislike_see_death_1", "That's one less problem to worry about.");
stringFiles[957].addEntry("imperial_like_farewell_1", "Good day to you sir.");
stringFiles[957].addEntry("imperial_like_greeting_1", "Good day!  What can I do for you?");
stringFiles[957].addEntry("imperial_like_see_attack_1", "Guards!  Help this man!");
