stringFiles[960] = new StringFile("npc_mission/npc_mission_01");
stringFiles[960].addEntry("npc_msn_01_busy_01", "What would you know about it? Tell me what you want or get out of here!");
stringFiles[960].addEntry("npc_msn_01_decline", "Well fine. I didn't want your help anyways. ");
stringFiles[960].addEntry("npc_msn_01_friend_greeting_01", "Well, hello!");
stringFiles[960].addEntry("npc_msn_01_friend_greeting_02", "Nice to see you again.");
stringFiles[960].addEntry("npc_msn_01_friend_greeting_onmission", "Aren't you supposed to be helping my friend, here?");
stringFiles[960].addEntry("npc_msn_01_friend_work_01", "You should speak to my friend. There's work to be done, but it's far too dangerous for me!");
stringFiles[960].addEntry("npc_msn_01_greeting_01", "Yes? You know this isn't exactly the BEST time to interrupt me.");
stringFiles[960].addEntry("npc_msn_01_greeting_02", "You again.");
stringFiles[960].addEntry("npc_msn_01_greeting_onmission", "I don't want to talk again until you've finished what I've asked you to do.");
stringFiles[960].addEntry("npc_msn_01_greeting_onothermission", "You need to finish all of your other tasks before we can talk.");
stringFiles[960].addEntry("npc_msn_01_presp_getmission_01", "I'm ready for some action. What do you have for me?");
stringFiles[960].addEntry("npc_msn_01_presp_getmission_02", "I would be happy to help you out. What can I do?");
stringFiles[960].addEntry("npc_msn_01_presp_getmission_03", "Can we skip the hassle and talk about the job, please?");
stringFiles[960].addEntry("npc_msn_01_presp_getmission_04", "I'm not looking for trouble, just a job.");
stringFiles[960].addEntry("npc_msn_01_presp_getmission_05", "I want a job. Don't you have something that you need done?");
stringFiles[960].addEntry("npc_msn_01_presp_greeting_01", "I'm looking for work.");
stringFiles[960].addEntry("npc_msn_01_presp_greeting_02", "You don't look busy to me.");
stringFiles[960].addEntry("npc_msn_01_work_01", "That's nothing new. Your kind is always looking for odd jobs, aren't they?");
stringFiles[960].addEntry("npc_msn_01_work_02", "Hmmm.... Now that I think about it, you might be able to help me out.");

stringFiles[961] = new StringFile("npc_mission/npc_mission_02");
stringFiles[961].addEntry("npc_msn_02_busy_01", "I've been waiting for someone to help me.  You are here to help right?");
stringFiles[961].addEntry("npc_msn_02_decline", "Oh my.  Well, I'll have to wait for someone else then...");
stringFiles[961].addEntry("npc_msn_02_friend_greeting_01", "Well, hello!");
stringFiles[961].addEntry("npc_msn_02_friend_greeting_02", "Nice to see you again.");
stringFiles[961].addEntry("npc_msn_02_friend_greeting_onmission", "Aren't you supposed to be helping my friend, here?");
stringFiles[961].addEntry("npc_msn_02_friend_work_01", "You should speak to my friend. There's work to be done, but it's far too dangerous for me!");
stringFiles[961].addEntry("npc_msn_02_greeting_01", "Oh thank the maker!  I've been waiting for you all day!");
stringFiles[961].addEntry("npc_msn_02_greeting_02", "You again.");
stringFiles[961].addEntry("npc_msn_02_greeting_onmission", "I need you to finish that task we talked about before we do anything else.");
stringFiles[961].addEntry("npc_msn_02_greeting_onothermission", "You need to finish all of your other tasks before we can talk.");
stringFiles[961].addEntry("npc_msn_02_presp_getmission_01", "Tell me what it is you need done.");
stringFiles[961].addEntry("npc_msn_02_presp_getmission_02", "Let's get started then.  What can I do for you?");
stringFiles[961].addEntry("npc_msn_02_presp_getmission_03", "What is it I can do for you?");
stringFiles[961].addEntry("npc_msn_02_presp_getmission_04", "I didn't know you knew who I was.");
stringFiles[961].addEntry("npc_msn_02_presp_getmission_05", "What is it you need me to do?");
stringFiles[961].addEntry("npc_msn_02_presp_greeting_01", "Is there something I can do for you?");
stringFiles[961].addEntry("npc_msn_02_presp_greeting_02", "You've been waiting for me?");
stringFiles[961].addEntry("npc_msn_02_work_01", "Absolutely.  I'm desperately in need of some help.");
stringFiles[961].addEntry("npc_msn_02_work_02", "I desperately need someone to help me out.");

stringFiles[962] = new StringFile("npc_mission/npc_mission_03");
stringFiles[962].addEntry("npc_msn_03_busy_01", "Don't act like you don't know!");
stringFiles[962].addEntry("npc_msn_03_decline", "Oh my.  Well, I'll have to wait for someone else then...");
stringFiles[962].addEntry("npc_msn_03_done_01", "My problems are my own...");
stringFiles[962].addEntry("npc_msn_03_friend_greeting_01", "Well, hello!");
stringFiles[962].addEntry("npc_msn_03_friend_greeting_02", "Nice to see you again.");
stringFiles[962].addEntry("npc_msn_03_friend_greeting_onmission", "Aren't you supposed to be helping my friend, here?");
stringFiles[962].addEntry("npc_msn_03_friend_work_01", "You should speak to my friend. There's work to be done, but it's far too dangerous for me!");
stringFiles[962].addEntry("npc_msn_03_greeting_01", "Wait...who are you?  You're not with THEM are you?");
stringFiles[962].addEntry("npc_msn_03_greeting_02", "You again.");
stringFiles[962].addEntry("npc_msn_03_greeting_onmission", "I'm starting to lose my faith in you.  I understand you haven't finished that job we talked about...");
stringFiles[962].addEntry("npc_msn_03_greeting_onothermission", "Aren't you a little busy to be talking to me right now?");
stringFiles[962].addEntry("npc_msn_03_presp_getmission_01", "What can I do?");
stringFiles[962].addEntry("npc_msn_03_presp_getmission_02", "Let's get started then.  What can I do for you?");
stringFiles[962].addEntry("npc_msn_03_presp_getmission_03", "No really.  I need some work.");
stringFiles[962].addEntry("npc_msn_03_presp_getmission_04", "You seem upset...can I help out?");
stringFiles[962].addEntry("npc_msn_03_presp_getmission_05", "You've got some serious problems...");
stringFiles[962].addEntry("npc_msn_03_presp_greeting_01", "Actually I'm looking for some work.");
stringFiles[962].addEntry("npc_msn_03_presp_greeting_02", "With WHO?");
stringFiles[962].addEntry("npc_msn_03_work_01", "Sure you are...working against me, right?");
stringFiles[962].addEntry("npc_msn_03_work_02", "There might be something you can do...if I can trust you...");

stringFiles[963] = new StringFile("npc_mission/npc_mission_04");
stringFiles[963].addEntry("npc_msn_04_busy_01", "Not only are you late you're incompetent?  Is that what's happened?");
stringFiles[963].addEntry("npc_msn_04_decline", "Oh my.  Well, I'll have to wait for someone else then...");
stringFiles[963].addEntry("npc_msn_04_done_01", "Good, get out of my sight.  I've had it with you too.");
stringFiles[963].addEntry("npc_msn_04_friend_greeting_01", "Well, hello!");
stringFiles[963].addEntry("npc_msn_04_friend_greeting_02", "Nice to see you again.");
stringFiles[963].addEntry("npc_msn_04_friend_greeting_onmission", "Aren't you supposed to be helping my friend, here?");
stringFiles[963].addEntry("npc_msn_04_friend_work_01", "You should speak to my friend. There's work to be done, but it's far too dangerous for me!");
stringFiles[963].addEntry("npc_msn_04_greeting_01", "Well it's about time you showed up.");
stringFiles[963].addEntry("npc_msn_04_greeting_02", "You again.");
stringFiles[963].addEntry("npc_msn_04_greeting_onmission", "Are you STILL not done with that job?");
stringFiles[963].addEntry("npc_msn_04_greeting_onothermission", "Aren't you a little busy to be talking to me right now?");
stringFiles[963].addEntry("npc_msn_04_presp_getmission_01", "Well, let's get to it then.");
stringFiles[963].addEntry("npc_msn_04_presp_getmission_02", "I can do whatever needs to be done.");
stringFiles[963].addEntry("npc_msn_04_presp_getmission_03", "I guess so.");
stringFiles[963].addEntry("npc_msn_04_presp_getmission_04", "What is your problem?");
stringFiles[963].addEntry("npc_msn_04_presp_getmission_05", "I've had about enough of you.");
stringFiles[963].addEntry("npc_msn_04_presp_greeting_01", "I need a job.");
stringFiles[963].addEntry("npc_msn_04_presp_greeting_02", "About time?  What do you mean?");
stringFiles[963].addEntry("npc_msn_04_work_01", "Doesn't everybody?");
stringFiles[963].addEntry("npc_msn_04_work_02", "I need this job done now.  Not later.  Now.");

stringFiles[964] = new StringFile("npc_mission/npc_mission_05");
stringFiles[964].addEntry("npc_msn_05_busy_01", "Of course.  Are you interested in something to do?");
stringFiles[964].addEntry("npc_msn_05_decline", "Oh my.  Well, I'll have to wait for someone else then...");
stringFiles[964].addEntry("npc_msn_05_done_01", "Well, come back if you change your mind.");
stringFiles[964].addEntry("npc_msn_05_friend_greeting_01", "Well, hello!");
stringFiles[964].addEntry("npc_msn_05_friend_greeting_02", "Nice to see you again.");
stringFiles[964].addEntry("npc_msn_05_friend_greeting_onmission", "Aren't you supposed to be helping my friend, here?");
stringFiles[964].addEntry("npc_msn_05_friend_work_01", "You should speak to my friend. There's work to be done, but it's far too dangerous for me!");
stringFiles[964].addEntry("npc_msn_05_greeting_01", "Hi.  I think you probably need some work.");
stringFiles[964].addEntry("npc_msn_05_greeting_02", "You again.");
stringFiles[964].addEntry("npc_msn_05_greeting_onmission", "I'm not going to deal with you until you finish your job.");
stringFiles[964].addEntry("npc_msn_05_greeting_onothermission", "You look like you're already busy.");
stringFiles[964].addEntry("npc_msn_05_presp_getmission_01", "Let's hear what it is.");
stringFiles[964].addEntry("npc_msn_05_presp_getmission_02", "Do you have a job?");
stringFiles[964].addEntry("npc_msn_05_presp_getmission_03", "So do you have something for me?");
stringFiles[964].addEntry("npc_msn_05_presp_getmission_04", "Tell me about the job.");
stringFiles[964].addEntry("npc_msn_05_presp_getmission_05", "Actually, I'm not ready to work right now.");
stringFiles[964].addEntry("npc_msn_05_presp_greeting_01", "That's right.");
stringFiles[964].addEntry("npc_msn_05_presp_greeting_02", "Do you have work?");
stringFiles[964].addEntry("npc_msn_05_work_01", "I figured as much.");
stringFiles[964].addEntry("npc_msn_05_work_02", "I've got something you can do.");

stringFiles[965] = new StringFile("npc_mission/static_businessman_deliver");
stringFiles[965].addEntry("cantwork", "I understand you're already working for someone else.  Come back when you're done with that job.");
stringFiles[965].addEntry("gotowork", "I need you to finish that task I gave you earlier.  Ok?");
stringFiles[965].addEntry("not_it", "No, sorry, that's not the item I was looking for...");
stringFiles[965].addEntry("npc_1_1", "My partner needs to get his briefcase back!  He left for a meeting without it.  If you can take it to him I'll have him give you some engraved pens from our company business.");
stringFiles[965].addEntry("npc_1_2", "My partner was on his way to an auction to sell off some of our assets.  We need the money to keep our business afloat, but he forgot one of the items we were selling.  Can you take it to him?  He's right outside of town.");
stringFiles[965].addEntry("npc_2_1", "Excellent.  He'll pay you when you make the delivery.");
stringFiles[965].addEntry("npc_2_2", "Great.  I'll make sure he gets the message that you're coming.");
stringFiles[965].addEntry("npc_3_1", "Well, if you can't help me I hope I can find someone who can.");
stringFiles[965].addEntry("npc_3_2", "That's too bad.  I'll find somebody useful.");
stringFiles[965].addEntry("npc_4_1", "All the paperwork that needs to be signed at the meeting.  It's vitally important that it get there.");
stringFiles[965].addEntry("npc_4_2", "It's an autographed trophy from some sports figure.  I don't know who he is, but I want to get it to him so he can sell it.");
stringFiles[965].addEntry("npc_reward_1", "Here you go.  It needs some ink, but you'll never have one better.");
stringFiles[965].addEntry("npc_reward_2", "Here you go.  See I had good seats, and I didn't let them tear it.  You should be able to get something for it if you want.");
stringFiles[965].addEntry("player_1_1", "Sure I'll drop it off.");
stringFiles[965].addEntry("player_1_2", "No problem.  I was looking for something to do.");
stringFiles[965].addEntry("player_2_1", "Nah, I don't feel like it.");
stringFiles[965].addEntry("player_2_2", "Sorry, I'm a bit busy at the moment.");
stringFiles[965].addEntry("player_3_1", "What was in the briefcase?");
stringFiles[965].addEntry("player_3_2", "What is the item exactly?");

stringFiles[966] = new StringFile("npc_mission/static_businessman_destroy");
stringFiles[966].addEntry("cantwork", "I understand you're already working for someone else.  Come back when you're done with that job.");
stringFiles[966].addEntry("gotowork", "I need you to finish that task I gave you earlier.  Ok?");
stringFiles[966].addEntry("not_it", "No, sorry, that's not the item I was looking for...");
stringFiles[966].addEntry("npc_1_1", "An industrial spy has decided that the best way to help his company is by becoming a murderer and killing our top executives.  I want this guy eliminated, and I don't care to know the details.  Up for this?");
stringFiles[966].addEntry("npc_1_2", "There's a madman claiming to be a business executive killing young Twilek women on this planet.  I know where he is, but the police won't listen to me.  I'll pay you myself if you'll take care of this.");
stringFiles[966].addEntry("npc_2_1", "Thank you...I'll be waiting anxiously for your return.");
stringFiles[966].addEntry("npc_2_2", "Great!  Hurry back.");
stringFiles[966].addEntry("npc_3_1", "Surely somebody will be able to help me.  Thanks for nothing, though.");
stringFiles[966].addEntry("npc_3_2", "That's too bad.  I'll find somebody useful.");
stringFiles[966].addEntry("npc_4_1", "I can't discuss it for legal reasons.");
stringFiles[966].addEntry("npc_4_2", "I'm not sure.  Maybe he was jilted by one.  Or maybe he's just crazy.  Does the why really matter at this point?");
stringFiles[966].addEntry("npc_reward_1", "Here you go.  It needs some ink, but you'll never have one better.");
stringFiles[966].addEntry("npc_reward_2", "Here you go.  See I had good seats, and I didn't let them tear it.  You should be able to get something for it if you want.");
stringFiles[966].addEntry("player_1_1", "I'll be back before you know it.");
stringFiles[966].addEntry("player_1_2", "I'll take care of it.  Someone has to.");
stringFiles[966].addEntry("player_2_1", "There's no way.  Sounds dangerous.");
stringFiles[966].addEntry("player_2_2", "Nah.  It's not my problem.");
stringFiles[966].addEntry("player_3_1", "Who does he work for?");
stringFiles[966].addEntry("player_3_2", "Why Twileks?");

stringFiles[967] = new StringFile("npc_mission/static_businessman_escort");
stringFiles[967].addEntry("cantwork", "I understand you're already working for someone else.  Come back when you're done with that job.");
stringFiles[967].addEntry("dontknowyou", "I don't know who you are, but I'm not going with you.");
stringFiles[967].addEntry("escortother", "I don't think I'm the person you're looking for.");
stringFiles[967].addEntry("gotowork", "I need you to finish that task I gave you earlier.  Ok?");
stringFiles[967].addEntry("not_it", "No, sorry, that's not the item I was looking for...");
stringFiles[967].addEntry("npc_1_1", "My partner needs to get back here fast.  We're going to be late for a meeting and I'm all alone.  Can you go get my partner?");
stringFiles[967].addEntry("npc_1_2", "My partner was at an auction selling some assets for capital.  I need somone to find and bring them back.  can you help?");
stringFiles[967].addEntry("npc_2_1", "Excellent.  We'll pay you when you get back.");
stringFiles[967].addEntry("npc_2_2", "Great.  I'll make sure the message gets through that you're coming.");
stringFiles[967].addEntry("npc_3_1", "Well, if you can't help me I hope I can find someone who can.");
stringFiles[967].addEntry("npc_3_2", "That's too bad.  I'll find somebody useful.");
stringFiles[967].addEntry("npc_4_1", "Merger.  There's a lot of paperwork to sign and I'm not authorized to do it alone.");
stringFiles[967].addEntry("npc_4_2", "It's an autographed trophy from some sports figure.  I don't know who he is, but apparently it sold well.");
stringFiles[967].addEntry("npc_reward_1", "Here you go.  It needs some ink, but you'll never have one better.");
stringFiles[967].addEntry("npc_reward_2", "Here you go.  See I had good seats, and I didn't let them tear it.  You should be able to get something for it if you want.");
stringFiles[967].addEntry("npc_takeme_1", "Great, you're here.  We don't want to be late for this meeting so let's get back quickly.");
stringFiles[967].addEntry("npc_takeme_2", "Oh good, you made it.  I got the money transferred to our bank, but I'm lost out here.  Should have hired a guide, huh?");
stringFiles[967].addEntry("player_1_1", "Sure I'll find your friend.");
stringFiles[967].addEntry("player_1_2", "No problem.  I was looking for something to do.");
stringFiles[967].addEntry("player_2_1", "Nah, I don't feel like it.");
stringFiles[967].addEntry("player_2_2", "Sorry, I'm a bit busy at the moment.");
stringFiles[967].addEntry("player_3_1", "What kind of meeting is it?");
stringFiles[967].addEntry("player_3_2", "What were you selling?");

stringFiles[968] = new StringFile("npc_mission/static_businessman_fetch");
stringFiles[968].addEntry("cantwork", "I understand you're already working for someone else.  Come back when you're done with that job.");
stringFiles[968].addEntry("gotowork", "I need you to finish that task I gave you earlier.  Ok?");
stringFiles[968].addEntry("not_it", "No, sorry, that's not the item I was looking for...");
stringFiles[968].addEntry("npc_1_1", "I had a lot of important paperwork in my briefcase, and now it's gone!  Some thief came by and grabbed it out of my hands.  If you can get it I'll give you this engraved writing stylus I got when I got my promotion.");
stringFiles[968].addEntry("npc_1_2", "I had an autographed ball from my favorite player in the league, and somebody took it!  If you can get it back for me I'll give you this collector's item ticket from last year's championships.  It's worth plenty.");
stringFiles[968].addEntry("npc_2_1", "Thank you...I'll be waiting anxiously for your return.");
stringFiles[968].addEntry("npc_2_2", "Great!  Hurry back.");
stringFiles[968].addEntry("npc_3_1", "Surely somebody will be able to help me.  Thanks for nothing, though.");
stringFiles[968].addEntry("npc_3_2", "That's too bad.  I'll find somebody useful.");
stringFiles[968].addEntry("npc_4_1", "It was mostly my personal accounting, but there are some sensitive documents in there that I can't discuss.");
stringFiles[968].addEntry("npc_4_2", "Don't you follow sports at all?  If you did you'd know what I was talking about.");
stringFiles[968].addEntry("npc_reward_1", "Here you go.  It needs some ink, but you'll never have one better.");
stringFiles[968].addEntry("npc_reward_2", "Here you go.  See I had good seats, and I didn't let them tear it.  You should be able to get something for it if you want.");
stringFiles[968].addEntry("player_1_1", "I'll be back before you know it.");
stringFiles[968].addEntry("player_1_2", "I'll be right back with your ball kid.");
stringFiles[968].addEntry("player_2_1", "There's no way.  I'm too tired right now.");
stringFiles[968].addEntry("player_2_2", "Nah.  I don't care about sports.");
stringFiles[968].addEntry("player_3_1", "What kind of documents did you have?");
stringFiles[968].addEntry("player_3_2", "What league are you talking about?");

stringFiles[969] = new StringFile("npc_mission/static_criminal_deliver");
stringFiles[969].addEntry("cantwork", "I understand you're already working for someone else.  Come back when you're done with that job.");
stringFiles[969].addEntry("gotowork", "I need you to finish that task I gave you earlier.  Ok?");
stringFiles[969].addEntry("not_it", "No, sorry, that's not the item I was looking for...");
stringFiles[969].addEntry("npc_1_1", "You ever hear of the Black Sun Pirates?  They robbed me and I want to pay them back.  Unfortunately, I need to get one of their medallions to get inside their base.  Can you help me get one?");
stringFiles[969].addEntry("npc_1_2", "I made a terrible mistake and got busted on camera stealing some credits from a merchant.  The trial's coming up soon and I need someone to get that camera.  I can tell you where it's at if you'll get it.");
stringFiles[969].addEntry("npc_1_3", "I've been collecting memorabilia of the Dark Jedi.  I know a guy who has a Medallion that they used.  Get it for me and I'll give you these broken holocron pieces.  I've got tons of holocrons.  They're bound to be worth something.");
stringFiles[969].addEntry("npc_1_4", "I need an electronic key to break into this warehouse I've been casing, but one of my rivals has it.  Get it for me and I'll give you some of the loot I got on my last job.");
stringFiles[969].addEntry("npc_2_1", "Good.  Get back as soon as you can and I'll get you a shisa.  You can use it in your home as a decoration, or sell it, I don't care either way.");
stringFiles[969].addEntry("npc_2_2", "Good.  As soon as you return I'll give you the decryptor.");
stringFiles[969].addEntry("npc_2_3", "You do the work, you get paid.  I'll be here.");
stringFiles[969].addEntry("npc_2_4", "Great.  I've got just the thing for you.  Let me know when you're back.");
stringFiles[969].addEntry("npc_3_1", "Too bad.  I would have given you a nice gift.");
stringFiles[969].addEntry("npc_3_2", "Well, guess I'll have to find somebody else then.");
stringFiles[969].addEntry("npc_3_3", "Not much I can do about it I guess, if you're not good enough.");
stringFiles[969].addEntry("npc_3_4", "Well, you'll never be a criminal in this town.");
stringFiles[969].addEntry("npc_4_1", "They have too many members to know each other, so anyone with a medallion can get into their areas.  If I had one I could pass myself off as a member of the group.");
stringFiles[969].addEntry("npc_4_2", "I paid off some guys and found out it's being delivered to a highly secure area today.  You can get it on route before the guy gets there.");
stringFiles[969].addEntry("npc_4_3", "You could try to put 'em back together.  Or find someone else who collects them and sell them maybe?  I don't know, but I know they're worth something.");
stringFiles[969].addEntry("npc_4_4", "He stole it before I could get to it.  He'll rob the warehouse instead of me if you don't get it for me.  I need that key!");
stringFiles[969].addEntry("npc_reward_1", "Here's that shisa I promised ya.  I'll just put it here in your pack.");
stringFiles[969].addEntry("npc_reward_2", "Here's the decryptor.  It doesn't work all the time, but I'm sure you'll find a use for it.");
stringFiles[969].addEntry("npc_reward_3", "Here they are.  Careful, they have sharp edges.");
stringFiles[969].addEntry("npc_reward_4", "Here you go.  I took this speaker from a cantina I robbed.  It'll go nicely in your house.");
stringFiles[969].addEntry("player_1_1", "Ok, I'll do it.");
stringFiles[969].addEntry("player_1_2", "Yeah, I can get that, no problem.");
stringFiles[969].addEntry("player_1_3", "Yeah, I can do it.  ");
stringFiles[969].addEntry("player_1_4", "I can do it.  No problem.");
stringFiles[969].addEntry("player_2_1", "Sounds dangerous.  I don't think I'm up to it.");
stringFiles[969].addEntry("player_2_2", "That's too much work.  I'm not doing it.");
stringFiles[969].addEntry("player_2_3", "Too much work for me.");
stringFiles[969].addEntry("player_2_4", "Thieves should do their own dirty work.");
stringFiles[969].addEntry("player_3_1", "How is a medallion going to help you?");
stringFiles[969].addEntry("player_3_2", "How do you know where the camera is?");
stringFiles[969].addEntry("player_3_3", "What can I do with broken pieces?");
stringFiles[969].addEntry("player_3_4", "How did your rival get the key?");

stringFiles[970] = new StringFile("npc_mission/static_criminal_escort");
stringFiles[970].addEntry("cantwork", "I understand you're already working for someone else.  Come back when you're done with that job.");
stringFiles[970].addEntry("dontknowyou", "I'm not sure who you are, but I'm not following you back to town.  No way.");
stringFiles[970].addEntry("gotowork", "I need you to finish that task I gave you earlier.  Ok?");
stringFiles[970].addEntry("not_it", "No, sorry, that's not the item I was looking for...");
stringFiles[970].addEntry("npc_1_1", "A friend of mine got mugged by black sun pirates and is too scared to come back to town.  I need someone to go make sure they can find their way back here.  Can you do it?");
stringFiles[970].addEntry("npc_1_2", "My partner has all our cash, but got lost in the wilderness.  I need someone to escort them back here to me.");
stringFiles[970].addEntry("npc_1_3", "Are you available to help me out with something?  I got somebody new coming in and I need you to bring them straight to me.  Can you do that?");
stringFiles[970].addEntry("npc_1_4", "My partner was trying to avoid some imperial patrols and managed to get lost outside of town.  Can you go out there and make sure there's no trouble getting back to me?");
stringFiles[970].addEntry("npc_2_1", "Good.  Get back as soon as you can and I'll get you a shisa.  You can use it in your home as a decoration, or sell it, I don't care either way.");
stringFiles[970].addEntry("npc_2_2", "Good.  As soon as you return I'll give you something nice.");
stringFiles[970].addEntry("npc_2_3", "You do the work, you get paid.  I'll be here.");
stringFiles[970].addEntry("npc_2_4", "Great.  I've got just the thing for you.  Let me know when you're back.");
stringFiles[970].addEntry("npc_3_1", "Too bad.  I would have given you a nice gift.");
stringFiles[970].addEntry("npc_3_2", "Well, guess I'll have to find somebody else then.");
stringFiles[970].addEntry("npc_3_3", "Not much I can do about it I guess, if you're not good enough.");
stringFiles[970].addEntry("npc_3_4", "Well, you'll never be a criminal in this town.");
stringFiles[970].addEntry("npc_4_1", "No, I think they've given up.  There might be some still around, but this should be pretty simple.");
stringFiles[970].addEntry("npc_4_2", "I don't think you need to know that just now.  Just bring my friend here.");
stringFiles[970].addEntry("npc_4_3", "Brand new.  I haven't even met them.  I don't even know if it's a male or a female!");
stringFiles[970].addEntry("npc_4_4", "No, they've given up.  Any imperials you see out there will just be a coincidence.");
stringFiles[970].addEntry("npc_reward_1", "Here's that shisa I promised ya.  I'll just put it here in your pack.");
stringFiles[970].addEntry("npc_reward_2", "Here's the decryptor.  It doesn't work all the time, but I'm sure you'll find a use for it.");
stringFiles[970].addEntry("npc_reward_3", "Here they are.  Careful, they have sharp edges.");
stringFiles[970].addEntry("npc_reward_4", "Here you go.  I took this speaker from a cantina I robbed.  It'll go nicely in your house.");
stringFiles[970].addEntry("npc_takeme_1", "Finally.  I was about to give up and try finding my way in on my own.");
stringFiles[970].addEntry("npc_takeme_2", "You're here to take me back?  Don't worry about the money.  I hid it.  It's not on me anymore.  Just get me to my friend.");
stringFiles[970].addEntry("npc_takeme_3", "Great!  I need you to take me to my new boss.  I don't even know who it is yet.");
stringFiles[970].addEntry("npc_takeme_4", "Quick, let's get back before the imperials start looking around for me again.");
stringFiles[970].addEntry("otherescort", "I think you're here to take someone else back.");
stringFiles[970].addEntry("player_1_1", "Ok, I'll do it.");
stringFiles[970].addEntry("player_1_2", "Yeah, I can do that, no problem.");
stringFiles[970].addEntry("player_1_3", "Yeah, I can do it.  ");
stringFiles[970].addEntry("player_1_4", "I can do it.  No problem.");
stringFiles[970].addEntry("player_2_1", "Sounds dangerous.  I don't think I'm up to it.");
stringFiles[970].addEntry("player_2_2", "That's too much work.  I'm not doing it.");
stringFiles[970].addEntry("player_2_3", "Too much work for me.");
stringFiles[970].addEntry("player_2_4", "Thieves should do their own dirty work.");
stringFiles[970].addEntry("player_3_1", "Are there still Black Sun Pirates out there?");
stringFiles[970].addEntry("player_3_2", "How much cash was there?");
stringFiles[970].addEntry("player_3_3", "How new is this person?");
stringFiles[970].addEntry("player_3_4", "Are the imperials still snooping around?");

stringFiles[971] = new StringFile("npc_mission/static_criminal_fetch");
