stringFiles[1022].addEntry("a_accept_offer_act", "");
stringFiles[1022].addEntry("a_accept_offer_chat", "");
stringFiles[1022].addEntry("a_accept_offer_mood", "doubtful");
stringFiles[1022].addEntry("a_brushoff", "Go away, stranger. And thanks for the help. None of these others know it, but I was the one with the poison. Now that that pathetic fool is out of the way, nothing stands between me and the money.");
stringFiles[1022].addEntry("a_brushoff_act", "");
stringFiles[1022].addEntry("a_brushoff_chat", "whisper");
stringFiles[1022].addEntry("a_brushoff_mood", "evil");
