stringFiles[1046].addEntry("ch_terminal_challenge_wrong_rank", "That player has not issued a challenge against your current rank.");
stringFiles[1046].addEntry("ch_terminal_choose_challenge", "Choose the challenger that you wish to combat in defense of your rank's honor!");
stringFiles[1046].addEntry("ch_terminal_demote_rank_penalty", "The members of rank %DI have failed to answer numerous challenges issued by the Dark Jedi of the enclave.  As a result, the entire rank has been demoted to rank zero.  Weakness cannot be tolerated in the Council.");
stringFiles[1046].addEntry("ch_terminal_demote_subject", "Rank Demoted!");
