stringFiles[1065] = new StringFile("quest/ground/c_darndroid1");
stringFiles[1065].addEntry("category", "Ground Quest");
stringFiles[1065].addEntry("journal_entry_description", "Valance Serth is missing.  His ship never landed in Moenia.  Find out what happened and save him.");
stringFiles[1065].addEntry("journal_entry_title", "Shuttle Crash");
stringFiles[1065].addEntry("task00_journal_entry_description", "C-3TC told you that his master is missing.");
stringFiles[1065].addEntry("task00_journal_entry_title", "Speak to C-3TC");
