stringFiles[1065].addEntry("task06_journal_entry_description", "Valance Serth rewards you for saving his life.");
stringFiles[1065].addEntry("task06_journal_entry_title", "Valance's Reward");
stringFiles[1065].addEntry("task07_journal_entry_description", "Accomplished mission.");
stringFiles[1065].addEntry("task07_journal_entry_title", "Mission Accomplished");
stringFiles[1065].addEntry("task08_journal_entry_description", "Speak to Amarent Loren.  Functionaries like him are underpaid.  A well-placed bribe would loosen his tongue.");
stringFiles[1065].addEntry("task08_journal_entry_title", "Speak to Amarent Loren");
stringFiles[1065].addEntry("task09_journal_entry_description", "You bribed Amarent Loren for his information.");
stringFiles[1065].addEntry("task09_journal_entry_title", "Bribed Amarent Loren");
stringFiles[1065].addEntry("task10_journal_entry_description", "Speak to Amarent Loren in Tyrena.  He can probably be bullied into giving you information.");
stringFiles[1065].addEntry("task10_journal_entry_title", "Speak to Amarent Loren");
stringFiles[1065].addEntry("task11_journal_entry_description", "You intimidated Amarent Loren.  He gave you the information that you need, but I'm sure he reported you to his superiors.");
stringFiles[1065].addEntry("task11_journal_entry_title", "Intimidated Amarent Loren");

