stringFiles[1119].addEntry("player_2_10", "That's too much work.  I'm not doing it.");
stringFiles[1119].addEntry("player_2_11", "Too much work for me.");
stringFiles[1119].addEntry("player_2_12", "Thieves should do their own dirty work.");
