stringFiles[1119].addEntry("player_3_1", "Are there still Black Sun Pirates out there?");
stringFiles[1119].addEntry("player_3_10", "How do you know where the camera is?");
stringFiles[1119].addEntry("player_3_11", "What can I do with broken pieces?");
stringFiles[1119].addEntry("player_3_12", "How did your rival get the key?");
stringFiles[1119].addEntry("player_3_2", "How much cash was there?");
stringFiles[1119].addEntry("player_3_3", "How new is this person?");
stringFiles[1119].addEntry("player_3_4", "Are the imperials still snooping around?");
stringFiles[1119].addEntry("player_3_5", "How will this medallion help?");
stringFiles[1119].addEntry("player_3_6", "What are they going to film?");
stringFiles[1119].addEntry("player_3_7", "Why does your, um, cousin, collect these things?");
stringFiles[1119].addEntry("player_3_8", "What's this key for?");
stringFiles[1119].addEntry("player_3_9", "How is a medallion going to help you?");
stringFiles[1119].addEntry("player_reset", "I'm getting out of this now, while I can.");
