stringFiles[1130] = new StringFile("reverse_engineering_tool");
stringFiles[1130].addEntry("already_engineered", "This item is the product of reverse engineering, and cannot be reverse engineered again.");
stringFiles[1130].addEntry("armorhpavg", "\\#FFFFFF Optimal Armor Points:");
stringFiles[1130].addEntry("armor_reward_generic", "Upon disassembling the armor, you discover that many were made from pieces of a rare armor type.  You manage to reassemble these into a complete item.");
