stringFiles[1146].addEntry("crafting_merchant_management_01", "Each rank in Management grants the Merchant the ability to place an additional vendor.");
stringFiles[1146].addEntry("crafting_merchant_management_02", "Each rank in Management grants the Merchant the ability to place an additional vendor.");
stringFiles[1146].addEntry("crafting_merchant_management_03", "Each rank in Management grants the Merchant the ability to place an additional vendor.");
