stringFiles[1154] = new StringFile("space/destroy_duty/corellia_privateer_11");
stringFiles[1154].addEntry("boss_detected", "Tactical Computer: < Vessel with veteran insignias on attack vector, weapon systems armed. >");
stringFiles[1154].addEntry("boss_title_1", "Ponias MorningGlory (Nym's Dark Enforcer)");
stringFiles[1154].addEntry("boss_title_2", "Geian Bladewrite (Nym's Dark Enforcer)");
stringFiles[1154].addEntry("boss_title_3", "Morar Deathslayer (Nym's Dark Enforcer)");
stringFiles[1154].addEntry("boss_title_4", "Atias Burninglight (Nym's Dark Enforcer)");
stringFiles[1154].addEntry("boss_title_5", "Kyax UnNamed (Nym's Dark Enforcer)");
stringFiles[1154].addEntry("complete", "Fantastic job pilot, we struck a huge blow to Nym today. Return to base for a well earned rest.");
stringFiles[1154].addEntry("dd_boss_taunt_1", "Muahahaha!");
stringFiles[1154].addEntry("dd_boss_taunt_2", "Your just another kill mark on my ship, fool!");
stringFiles[1154].addEntry("dd_boss_taunt_3", "The cat becomes the mouse. The tables are turned, scum!");
stringFiles[1154].addEntry("dd_boss_taunt_4", "Your flying skills remind me of a one winged Mynock!");
stringFiles[1154].addEntry("dd_boss_taunt_5", "I've never seen those moves from a  petty pilot before. No matter, prepare to die!");
stringFiles[1154].addEntry("duty_update", "Superior Command: < %TO >");
stringFiles[1154].addEntry("found_loc", "New coordinates of pirate activity has been uploaded to your nav computer. Go get them!");
stringFiles[1154].addEntry("level_boss", "Superior Command: < The Hidden Daggers has sent %TO to bring you down, proceed with caution. >");
stringFiles[1154].addEntry("level_boss_dead", "Amazing! Nym will not forget this day. Stand by for further orders.");
stringFiles[1154].addEntry("level_increase", "Nym's men are sending more reinforcements in responce to our attacks.");
stringFiles[1154].addEntry("targets_behind", "Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >");
stringFiles[1154].addEntry("targets_detected", "Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >");
stringFiles[1154].addEntry("taunt_1", "You think you can match the skill of Nym's pirates? I think not!");
stringFiles[1154].addEntry("taunt_2", "I will shred your ship, fool!");
stringFiles[1154].addEntry("taunt_3", "You always have to interfere, well this time you stuck your nose too deep!");
stringFiles[1154].addEntry("taunt_4", "You're fighting a uphill battle , and the hill just got steeper!");
stringFiles[1154].addEntry("taunt_5", "I have crushed greater things than you! In fact, I shot a Womprat back on Tatooine last week!");
stringFiles[1154].addEntry("title", "Strike a blow to Nym's Pirates.");

stringFiles[1155] = new StringFile("space/destroy_duty/corellia_privateer_9");
stringFiles[1155].addEntry("boss_detected", "Tactical Computer: < Vessel with veteran insignias on attack vector, weapon systems armed. >");
stringFiles[1155].addEntry("boss_title_1", "Experienced Pirate Pilot");
stringFiles[1155].addEntry("boss_title_2", "Veteran Pirate Pilot");
stringFiles[1155].addEntry("boss_title_3", "Grim Veteran Pirate Pilot");
stringFiles[1155].addEntry("boss_title_4", "Furious Veteran Pirate Pilot");
stringFiles[1155].addEntry("boss_title_5", "Ace Veteran Pirate Pilot");
stringFiles[1155].addEntry("complete", "Fantastic job pilot! We struck a blow to the Pirates that will take them a long time to recover from. Head back to base when ready.");
stringFiles[1155].addEntry("dd_boss_taunt_1", "Foolish puppet, you should have run while you had the chance!");
stringFiles[1155].addEntry("dd_boss_taunt_2", "To us you're just a anuiance, about to be squashed!");
stringFiles[1155].addEntry("dd_boss_taunt_3", "Too bad you ran in to me so early in your career, as I mark it's end!");
stringFiles[1155].addEntry("dd_boss_taunt_4", "Maybe I should fly using just one hand, to give you a chance?");
stringFiles[1155].addEntry("dd_boss_taunt_5", "Your pilot helmet will look good on my trophy rack, fool!");
stringFiles[1155].addEntry("duty_update", "Superior Command: < %TO >");
stringFiles[1155].addEntry("found_loc", "The next area of known Pirate activity has been uploaded to your nav computer, proceed when ready.");
stringFiles[1155].addEntry("level_boss", "Superior Command: < The Pirates have sent one of their best pilots to take care of you, be careful! >");
stringFiles[1155].addEntry("level_boss_dead", "That one has been a dread ever since he came to this sector, great work pilot!");
stringFiles[1155].addEntry("level_increase", "Sensors through out the sectors show increased Pirate activity in response to our attacks.");
stringFiles[1155].addEntry("targets_behind", "Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >");
stringFiles[1155].addEntry("targets_detected", "Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >");
stringFiles[1155].addEntry("taunt_1", "Youre not going to survive this fight!");
stringFiles[1155].addEntry("taunt_2", "You should turn back while you can!");
stringFiles[1155].addEntry("taunt_3", "Your about to learn the foolishness of messing with the Pirates!");
stringFiles[1155].addEntry("taunt_4", "You should never have come here, now you will never leave.");
stringFiles[1155].addEntry("taunt_5", "Time to add another puppet on my kill list!");
stringFiles[1155].addEntry("title", "Attack on the Pirates in Dantooine Sector");

