stringFiles[1287] = new StringFile("spacequest/assassinate/tatooine_rebel_4");
stringFiles[1287].addEntry("arrival_phase_1", "We are tracking the TIE Veteran, stand by pilot.");
stringFiles[1287].addEntry("arrival_phase_2", "Got him! Proceed to intercept and terminate him immediately. We will update his coordinates as he's moving.");
stringFiles[1287].addEntry("assassinate_success", "Very impressive pilot. The loss of that pilot will be a big blow to the Empire in this system. Return to base.");
stringFiles[1287].addEntry("assigned_delayed", "");
stringFiles[1287].addEntry("autorewardbody", "");
stringFiles[1287].addEntry("autorewardfrom", "");
stringFiles[1287].addEntry("autorewardsubject", "");
