stringFiles[1330] = new StringFile("spacequest/delivery_no_pickup/corellia_rebel_tier4_2_a");
stringFiles[1330].addEntry("arrived_at_delivery", "Dock with the smuggler and get out of there quickly before more of the Empire's goons show up.");
stringFiles[1330].addEntry("assigned_delayed", "");
stringFiles[1330].addEntry("attack_notify", "Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >");
stringFiles[1330].addEntry("attack_stopped", "Tactical Computer: < No more fighter vessels within sensor range. >");
stringFiles[1330].addEntry("autorewardbody", "");
stringFiles[1330].addEntry("autorewardfrom", "");
stringFiles[1330].addEntry("autorewardsubject", "");
