stringFiles[1331].addEntry("docking_started_delivery", "Standing by for docking sequence.");
stringFiles[1331].addEntry("failed_destroyed", "The mission is a wash, pilot. The delivery ship was destroyed. Return to base for debriefing.");
stringFiles[1331].addEntry("found_loc_d", "Transmitting coordinates of delivery location. Proceed to the waypoint and meet the drop-off vessel.");
stringFiles[1331].addEntry("hello_d", "Are you the agent I'm looking for? I'm ready to transfer the package. Do you copy?");
