stringFiles[1422].addEntry("boss_title_5", "Foe Hammer");
stringFiles[1422].addEntry("complete", "Good job, pilot! You've managed to do significant damage to Nym's forces in this sector. Return to base.");
stringFiles[1422].addEntry("dd_boss_taunt_1", "I want to hear you scream while I cut your ship open.");
stringFiles[1422].addEntry("dd_boss_taunt_2", "We won't hurt you, Imperial. We just want to play.");
stringFiles[1422].addEntry("dd_boss_taunt_3", "Nym says we should capture you, but I think I'm going to just space you.");
