stringFiles[1422].addEntry("quest_location_d", "Travel to the Lok system and attack Nym's fighters there. You will receive a Nav waypoint to areas under the control of Nym.");
stringFiles[1422].addEntry("quest_location_t", "Travel to the Lok System");
stringFiles[1422].addEntry("targets_behind", " \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets coming in from behind! \\#pcontrast3 >");
stringFiles[1422].addEntry("targets_detected", " \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets on incoming attack vector! \\#pcontrast3 >");
