stringFiles[1436].addEntry("targets_behind", "Tactical Computer: < Enemy fighters detected. >");
stringFiles[1436].addEntry("targets_detected", "Tactical Computer: < Enemy fighters detected. >");
stringFiles[1436].addEntry("taunt_1", "Prepare to become space dust.");
