stringFiles[1605] = new StringFile("spacequest/escort_duty/tatooine_rebel_7");
stringFiles[1605].addEntry("abort", "Abort code received. Heading back to base.");
stringFiles[1605].addEntry("arrived_at_loc", "Wait at this location. An Alliance refugee transport will arrive shortly.");
stringFiles[1605].addEntry("attack_notify", " \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostiles on approach vector to escort target! \\#pcontrast3 >");
stringFiles[1605].addEntry("attack_stopped", " \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile fighters eliminated. \\#pcontrast3 >");
stringFiles[1605].addEntry("complete", "Alliance HQ: < The refugees have made it through the region safely. Good job. >");
stringFiles[1605].addEntry("duty_update", " \\#pcontrast3 Alliance HQ: < \\#pcontrast1 %TO \\#pcontrast3 >");
stringFiles[1605].addEntry("escort_too_far1", "");
stringFiles[1605].addEntry("escort_too_far2", "");
