stringFiles[1704].addEntry("splitquestbody", "Imperial Transport ZE43/t requesting immediate fire support.  We are under attack by pirate forces.  We require an escort to a safe location.  Waypoint to our current coordinates attached...");
stringFiles[1704].addEntry("splitqurom", "Imperial Transport ZE43/t");
stringFiles[1704].addEntry("splitquestsubject", "Requesting Assistance!");
stringFiles[1704].addEntry("split_quest_alert", "Alert! Receiving distress signal from Imperial transport! The transport is on the run from Commerce Raiders. Stand by to escort transport through sector.");
