stringFiles[1772] = new StringFile("spacequest/recovery_duty/corellia_rebel_tier4_1");
stringFiles[1772].addEntry("abort", "Arr, you can't leave us now mate! Those TIE's will eat us alive!");
stringFiles[1772].addEntry("angry_disable", "You're crazy if you think you can get away with this Rebel!");
stringFiles[1772].addEntry("arrival_phase_1", "Alright Rebel, waiting for word of a position from our men. Stand by.");
stringFiles[1772].addEntry("arrival_phase_2", "They have arrived, intercept them! I will keep their position updated as fast as I can.");
stringFiles[1772].addEntry("attack_notify", "Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >");
