stringFiles[1772].addEntry("capture_phase_1_2", "Let 'em have it boys!");
stringFiles[1772].addEntry("capture_phase_1_3", "Surprise you Imperial fools!");
stringFiles[1772].addEntry("capture_phase_1_4", "It's party time!");
stringFiles[1772].addEntry("capture_phase_1_5", "Touch those guns and you die! This ship now belongs to Nym!");
stringFiles[1772].addEntry("capture_phase_2_1", "We're breaking down the door to the bridge now, the ship will be ours in a few seconds!");
stringFiles[1772].addEntry("capture_phase_2_2", "The ship is ours boys!");
stringFiles[1772].addEntry("capture_phase_2_3", "Break down that door men!");
stringFiles[1772].addEntry("capture_phase_2_4", "We are in contr.. take that Imperial scum! Well almost in control, give us a few more seconds.");
stringFiles[1772].addEntry("capture_phase_2_5", "I could do this all day, nothing better than stealing from the Empire!");
stringFiles[1772].addEntry("capture_started", "Nym Command Officer: < Our boys are getting rid of the crew now, stand by. >");
