stringFiles[1781].addEntry("capture_phase_2_2", "The Red Skulls will not stand for this.");
stringFiles[1781].addEntry("capture_phase_2_3", "I thought the Empire was fair and just...you have shattered my dreams.");
stringFiles[1781].addEntry("capture_phase_2_4", "I can't control my ship! You have done something to my computers!");
stringFiles[1781].addEntry("capture_phase_2_5", "One day I shall get my revenge.");
