stringFiles[1792] = new StringFile("spacequest/rescue/corellia_imperial_tier3_3");
stringFiles[1792].addEntry("abort", "Where are you going? I thought that I had information HQ wanted?");
stringFiles[1792].addEntry("arrival_phase_1", "Getting nav location of the damaged freighter. We believe it knows the location of the Rebel emissary to Nym in this system. Stand by.");
stringFiles[1792].addEntry("arrival_phase_2", "We have the location. Assist freighter with repairs and escort it back to HQ.");
stringFiles[1792].addEntry("assigned_delayed", "");
stringFiles[1792].addEntry("attack_notify", "\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>");
stringFiles[1792].addEntry("attack_stopped", "\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>");
