stringFiles[1811] = new StringFile("spacequest/rescue/tatooine_imperial_tier3_1_c");
stringFiles[1811].addEntry("abort", "What? You have aborted the attack! We cannot last without your protection...");
stringFiles[1811].addEntry("arrival_phase_1", "Getting arrival location of the supply freighter. It looks like she was hit pretty hard. Once you get to her, dock with her, and assist with any repairs you can.");
stringFiles[1811].addEntry("arrival_phase_2", "Current location of supply freighter sent to your nav computer. Help the supply freighter get under way and escort her to safety.");
