stringFiles[1837].addEntry("split_quest_alert_fail", "");
stringFiles[1837].addEntry("title", "Dathomir system: Save the Nym freighters from total annihilation.");
stringFiles[1837].addEntry("title_d", "Several Black Sun ship managed to slip by our and Nym's blockade and the mining vessels are under attack. Assist and save as many of them as you can.");

stringFiles[1838] = new StringFile("spacequest/space_battle/corellia_rebel_tier4_3");
