stringFiles[1838].addEntry("title", "Dathomir system: Help the Alliance attack on an Imperial space station.");
stringFiles[1838].addEntry("title_d", "Our squad has been assigned to assist in a guerilla strike on an Imperial space station. We need to pave the way through enemy defense for the Alliance B-Wing bombers.");

stringFiles[1839] = new StringFile("spacequest/space_battle/corellia_rebel_tier4_3_a");
