stringFiles[1854].addEntry("autorewardfrom", "");
stringFiles[1854].addEntry("autorewardsubject", "");
stringFiles[1854].addEntry("battle_abandoned", "");
stringFiles[1854].addEntry("battle_started", "May the force be with you my friends!");
stringFiles[1854].addEntry("enemies_arrived", "I'm getting reports of several advanced TIE ships in the enemy force, this will be rough.");
stringFiles[1854].addEntry("enemies_remain", "Tactical Computer: < Sensors show enemy target terminated. %DI enemy target(s) remain. >");
stringFiles[1854].addEntry("enemies_win", "Pull out pilot! Hopefully some of our other bomber squadrons have had better luck.");
