stringFiles[1868] = new StringFile("spacequest/space_battle/tatooine_rebel_tier3_3_a");
stringFiles[1868].addEntry("allies_arrived", "Good to see you pilot. I heard you were good, will be a pleasure to work with you.");
stringFiles[1868].addEntry("allies_remain", "Scythe Squadron Leader: < Ack, you Imperial scum, we will avenge him! >");
stringFiles[1868].addEntry("allies_win", "That should make the Empire think twice before messing with us again!");
stringFiles[1868].addEntry("assigned_delayed", "");
