stringFiles[1870].addEntry("title", "Dathomir system: Attack the Empires advanced fighters.");
stringFiles[1870].addEntry("title_d", "The Empire is testing out some of their new ships, lets give them a training they won't forget.");

stringFiles[1871] = new StringFile("spacequest/space_battle/tatooine_rebel_tier4_3");
stringFiles[1871].addEntry("allies_arrived", "Our fighter squadron has arrived, join up as fast as you can.");
