stringFiles[1875] = new StringFile("spacequest/survival/corellia_imperial_tier3_2_a");
stringFiles[1875].addEntry("arrived_at_loc", "Stand by to begin your transmission. Once that starts prepare for Nym's pirates to storm in. You will have to stay in the area until the entire broadcast is complete in order to get everyones attention.");
stringFiles[1875].addEntry("assigned_delayed", "");
stringFiles[1875].addEntry("attack_notify", "\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>");
stringFiles[1875].addEntry("attack_stopped", "\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>");
