stringFiles[1877] = new StringFile("spacequest/survival/corellia_imperial_tier3_4_b");
stringFiles[1877].addEntry("arrived_at_loc", "Stand by at this location. Nym's pirates are on an interception course.");
stringFiles[1877].addEntry("assigned_delayed", "");
stringFiles[1877].addEntry("attack_notify", "\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming.>");
stringFiles[1877].addEntry("attack_stopped", "\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>");
