stringFiles[1881] = new StringFile("spacequest/survival/corellia_rebel_tier3_2_b");
stringFiles[1881].addEntry("arrived_at_loc", "You have arrived at the intercept coordinates. I hope you're as good as I think, this will get rough.");
stringFiles[1881].addEntry("assigned_delayed", "");
stringFiles[1881].addEntry("attack_notify", "Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >");
