stringFiles[1903].addEntry("quest_defendpoint_d", "When you begin the scan you can expect to be attacked by Rebel fighters falling into our ambush. Defend yourself but do not leave the area until the operation is completed.");
stringFiles[1903].addEntry("quest_defendpoint_t", "Defend the Ambush Point");
