stringFiles[1912].addEntry("weapon_basic_launcher", "A standard wing mounted missile launcher.  Equip a missile pack into this launcher to make it operational.");
stringFiles[1912].addEntry("weapon_basic_missile_pack", "A standard pack of homing missiles designed for a standard wing mounted missile launcher.");
stringFiles[1912].addEntry("weapon_chaff_launcher", "A chaff launcher used to deter incoming missiles.");
stringFiles[1912].addEntry("weapon_chaff_pack", "Ammo pack for a chaff launcher.");
stringFiles[1912].addEntry("weapon_confuser_launcher", "An IFF Confuser launcher used to deter incoming missiles. Launches a small device that makes enemy missiles think they are headed toward a friendly target. More effective than Micro-Chaff.");
stringFiles[1912].addEntry("weapon_confuser_pack", "Ammo pack for a IFF Confuser launcher.");
stringFiles[1912].addEntry("weapon_decoy_launcher", "A sensor decoy system used to deter incoming missiles.");
