stringFiles[1920].addEntry("gotowork_1", "");
stringFiles[1920].addEntry("next", "");
stringFiles[1920].addEntry("notit_1", "");
stringFiles[1920].addEntry("notyet", "");
stringFiles[1920].addEntry("npc_1_1", "Hey you! Have you heard the new song playing in the cantina? The Empire's Slave is a band of musicians who have been singing about bringing down all kinds of government. Do you want to know where they might be playing next?");
stringFiles[1920].addEntry("npc_2_1", "They were saying that anyone who wants to help destroy all governments should show up at the Patriots' base of operations. Watch out, though, because they probably might think you work for either the Empire or the Rebellion.");
stringFiles[1920].addEntry("npc_3_1", "Yeah, you're probably one of those Imperials, or worse yet, one of those Rebels. You're just like those guys they were talking about. Well, you can go off and be a slave to them? I know I'm not!");
stringFiles[1920].addEntry("npc_4_1", "There's a group of guys who call themselves the Patriots, right? They're a bunch of Drall like me who want to smash every government to the ground, and they formed a band to spread the message! They are sooo wizard!");
stringFiles[1920].addEntry("npc_5_1", "");
stringFiles[1920].addEntry("npc_6_1", "");
stringFiles[1920].addEntry("npc_backtowork_1", "Good luck!");
stringFiles[1920].addEntry("npc_breech_1", "");
stringFiles[1920].addEntry("npc_dropoff_1", "");
stringFiles[1920].addEntry("npc_failure_1", "");
stringFiles[1920].addEntry("npc_more_1_1", "");
stringFiles[1920].addEntry("npc_more_2_1", "");
stringFiles[1920].addEntry("npc_more_3_1", "");
stringFiles[1920].addEntry("npc_noloc_1", "");
stringFiles[1920].addEntry("npc_reset", "So be it. Farewell.");
stringFiles[1920].addEntry("npc_reward_1", "");
stringFiles[1920].addEntry("npc_smuggle_1", "");
stringFiles[1920].addEntry("npc_takeme_1", "");
stringFiles[1920].addEntry("npc_work_1", "Did you find the Drall Patriots' hideout?");
stringFiles[1920].addEntry("otherescort_1", "");
stringFiles[1920].addEntry("player_1_1", "Sure, tell me.");
stringFiles[1920].addEntry("player_2_1", "Nope, not interested.");
stringFiles[1920].addEntry("player_3_1", "Who is The Empire's Slave?");
stringFiles[1920].addEntry("player_4_1", "");
stringFiles[1920].addEntry("player_5_1", "");
stringFiles[1920].addEntry("player_more_1_1", "");
stringFiles[1920].addEntry("player_more_2_1", "");
stringFiles[1920].addEntry("player_more_3_1", "");
stringFiles[1920].addEntry("player_reset", "No. I've decided not to go there.");
stringFiles[1920].addEntry("player_sorry", "Not yet. I am on my way there now.");
