stringFiles[1926].addEntry("return_waypoint_name_1", "");
stringFiles[1926].addEntry("waypoint_description_1", "According to the Imperial Officer, this area is home to aggressive Dantari");
stringFiles[1926].addEntry("waypoint_name_1", "Dantari Stronghold");

stringFiles[1927] = new StringFile("spawning/static_npc/herald_dantooine_mokk_stronghold");
