stringFiles[1935].addEntry("npc_reset", "AAAH! Fine!");
stringFiles[1935].addEntry("npc_reward_1", "");
stringFiles[1935].addEntry("npc_smuggle_1", "");
stringFiles[1935].addEntry("npc_takeme_1", "");
stringFiles[1935].addEntry("npc_work_1", "Did you find them?");
stringFiles[1935].addEntry("otherescort_1", "");
stringFiles[1935].addEntry("player_1_1", "Sure, tell me.");
stringFiles[1935].addEntry("player_2_1", "Sorry, I have no gripes with the Ewoks!");
stringFiles[1935].addEntry("player_3_1", "Easy, friend. Why are you so angry?");
stringFiles[1935].addEntry("player_4_1", "");
