stringFiles[1944].addEntry("waypoint_name_1", "Pirate Bunker");

stringFiles[1945] = new StringFile("spawning/static_npc/herald_naboo_pirate_pirate_rescue_ketter");
stringFiles[1945].addEntry("cant_work", "Go away an' let a pirate drink. Ye have too many things goin' on right now.");
stringFiles[1945].addEntry("dontknowyou_1", "Go away! I don't need your help.");
stringFiles[1945].addEntry("gotowork_1", "");
