stringFiles[1970].addEntry("npc_work_2", "Why haven't you found Valarian's compound guard?");
stringFiles[1970].addEntry("npc_work_3", "Where's the scientist?");
stringFiles[1970].addEntry("npc_work_4", "Did you take care of that little problem we were having?");
stringFiles[1970].addEntry("npc_work_5", "Did you take care of our little problem?");
stringFiles[1970].addEntry("npc_work_6", "Where's the egg?");
stringFiles[1970].addEntry("otherescort_1", "");
stringFiles[1970].addEntry("otherescort_2", "I'm waiting for somebody, and guess what?  It's not you!");
stringFiles[1970].addEntry("otherescort_3", "I'm waiting for someone, sorry, I can't talk.");
