stringFiles[1970].addEntry("player_1_2", "I would be happy to.");
stringFiles[1970].addEntry("player_1_3", "Ok, I'll go get him.");
stringFiles[1970].addEntry("player_1_4", "Got it.  Kill the killer.");
stringFiles[1970].addEntry("player_1_5", "I'll get right to it.");
stringFiles[1970].addEntry("player_1_6", "I'll do it.  I've been waiting for this...");
stringFiles[1970].addEntry("player_2_1", "I am not ready yet.");
stringFiles[1970].addEntry("player_2_2", "I can't do this right now.");
stringFiles[1970].addEntry("player_2_3", "This sounds like something someone else could do.");
stringFiles[1970].addEntry("player_2_4", "This sounds dangerous.");
stringFiles[1970].addEntry("player_2_5", "I'm a little busy.");
stringFiles[1970].addEntry("player_2_6", "I'll have to come back later.");
stringFiles[1970].addEntry("player_3_1", "Who is this assassin?");
stringFiles[1970].addEntry("player_3_2", "What's for lunch?");
stringFiles[1970].addEntry("player_3_3", "Won't he realize I'm not taking him to Jabba's?");
stringFiles[1970].addEntry("player_3_4", "Why don't we just hire this murderer?");
