stringFiles[1971].addEntry("npc_takeme_6", "");
stringFiles[1971].addEntry("npc_work_1", "Did you recover what I require?");
stringFiles[1971].addEntry("npc_work_2", "Will you please take care of Jabba's Enforcers? They could be here at any moment!");
stringFiles[1971].addEntry("npc_work_3", "Have you delivered the proclamation?");
stringFiles[1971].addEntry("npc_work_4", "Hey, did you make that pick up for me?");
stringFiles[1971].addEntry("npc_work_5", "How come I haven't heard about Jabba's thug dying yet?");
stringFiles[1971].addEntry("npc_work_6", "Where's the briefcase?");
stringFiles[1971].addEntry("otherescort_1", "");
