stringFiles[1971].addEntry("player_1_1", "Let's get started.");
stringFiles[1971].addEntry("player_1_2", "Sounds like fun.");
stringFiles[1971].addEntry("player_1_3", "Of course. What is it?");
stringFiles[1971].addEntry("player_1_4", "Sure, no problem.");
stringFiles[1971].addEntry("player_1_5", "I'm clear.  He's gone.");
stringFiles[1971].addEntry("player_1_6", "I'm on my way.");
stringFiles[1971].addEntry("player_2_1", "I can't help you right now.");
stringFiles[1971].addEntry("player_2_2", "I can't do this right now.");
stringFiles[1971].addEntry("player_2_3", "I'm not available at the moment.");
stringFiles[1971].addEntry("player_2_4", "Sorry, I'm busy right now.");
stringFiles[1971].addEntry("player_2_5", "This isn't my type of work.");
stringFiles[1971].addEntry("player_2_6", "This is too much work.");
stringFiles[1971].addEntry("player_3_1", "Who cares if you think I'm courageous?");
stringFiles[1971].addEntry("player_3_2", "Why would Jabba do this?");
stringFiles[1971].addEntry("player_3_3", "What are people hearing about me?");
stringFiles[1971].addEntry("player_3_4", "What's this thing I'm picking up?");
stringFiles[1971].addEntry("player_3_5", "What's the payout on this?");
