stringFiles[1976] = new StringFile("spice/spice");
stringFiles[1976].addEntry("bio_kliknik_fortitude_boost_consume", "Your innards harden.");
stringFiles[1976].addEntry("bio_kliknik_fortitude_boost_done", "The weakness passes as your body completes its cleansing.");
stringFiles[1976].addEntry("bio_kliknik_fortitude_boost_downer", "You weaken as your inner armor begins to dissolve.");
stringFiles[1976].addEntry("bio_kwi_adrenal_boost_consume", "Your body tingles as the adrenalin courses through your veins.");
stringFiles[1976].addEntry("bio_kwi_adrenal_boost_done", "You regain your composure.");
stringFiles[1976].addEntry("bio_kwi_adrenal_boost_downer", "You feel cold and begin to shake as the adrenalin dissipates.");
stringFiles[1976].addEntry("booster_blue_consume", "You consume the Booster Blue and feel a boost to your physical speed.");
stringFiles[1976].addEntry("booster_blue_done", "Your reaction time returns to normal as your body adjusts to the lack of Booster Blue.");
stringFiles[1976].addEntry("booster_blue_downer", "Your reaction time slows considerably as the Booster Blue's effects fade.");
stringFiles[1976].addEntry("crash_n_burn_consume", "You become intensely aware of your surroundings and filled with a sense of apathy.");
stringFiles[1976].addEntry("crash_n_burn_done", "The feeling of apathy from the Crash n' Burn leaves you.");
stringFiles[1976].addEntry("crash_n_burn_downer", "The awareness enhancing effects of the Crash n' Burn fade, but the feeling of apathy intensifies.");
stringFiles[1976].addEntry("droid_lube_consume", "The zypolene burns as you apply it, causing you to feel more resiliant.");
stringFiles[1976].addEntry("droid_lube_done", "The zypolene induced vulnerability has ended.");
stringFiles[1976].addEntry("droid_lube_downer", "The zypolene's effects fade, leaving you feeling vulnerable.");
stringFiles[1976].addEntry("giggledust_consume", "You feel light headed and filled with euphoria.");
stringFiles[1976].addEntry("giggledust_done", "The depression of the absense of Giggledust has faded.");
stringFiles[1976].addEntry("giggledust_downer", "The sense of euphoria from the Giggledust fades, leaving you feeling depressed.");
stringFiles[1976].addEntry("grey_gabaki_consume", "The Grey Gabaki fills you with a sharp sense of focus.");
stringFiles[1976].addEntry("grey_gabaki_done", "The drowsy feeling of the Grey Gabaki has passed.");
stringFiles[1976].addEntry("grey_gabaki_downer", "The focusing effects of the Grey Gabaki have left you feeling drowsy.");
stringFiles[1976].addEntry("gunjack_consume", "The Gunjack burns in your throat.  You feel an intense rush of physical strength.");
stringFiles[1976].addEntry("gunjack_done", "The sluggishness induced by the Gunjack seems to be gone.");
stringFiles[1976].addEntry("gunjack_downer", "The Gunjack's effects dissipate leaving you feeling weak and sluggish.");
stringFiles[1976].addEntry("kliknik_boost_consume", "Your innards harden.");
stringFiles[1976].addEntry("kliknik_boost_done", "The weakness passes as your body completes its cleansing.");
stringFiles[1976].addEntry("kliknik_boost_downer", "You weaken as your inner armor begins to dissolve.");
stringFiles[1976].addEntry("kwi_boost_consume", "Your body tingles as the adrenalin courses through your veins.");
stringFiles[1976].addEntry("kwi_boost_done", "You regain your composure.");
stringFiles[1976].addEntry("kwi_boost_downer", "You feel cold and begin to shake as the adrenalin dissipates.");
stringFiles[1976].addEntry("muon_gold_consume", "The Muon Gold irradiates your body increasing your mental clarity and focus.");
stringFiles[1976].addEntry("muon_gold_done", "The negative effects of the Muon Gold seem to have passed.");
stringFiles[1976].addEntry("muon_gold_downer", "The Muon Gold fades, leaves your mind feeling weak and slow.");
stringFiles[1976].addEntry("neutron_pixey_consume", "As you consume the Neutron Pixie you begin to feel light headed.");
stringFiles[1976].addEntry("neutron_pixey_done", "The negative effects of the Neutron Pixie seem to have left your body.");
stringFiles[1976].addEntry("neutron_pixey_downer", "The mind enhancing effects of the Neutron Pixie leave.  You have to fight to retain consciousness.");
stringFiles[1976].addEntry("pyrepenol_consume", "As you swallow the pyrepenol, you suddenly feel your muscles surge with strength.");
stringFiles[1976].addEntry("pyrepenol_done", "The aches in your muscles have ended.");
stringFiles[1976].addEntry("pyrepenol_downer", "Your stength enhancement fades, leaving your muscles sore and weak.");
stringFiles[1976].addEntry("scramjet_consume", "Your muscles burst with new strength as you consume the Scramjet.");
stringFiles[1976].addEntry("scramjet_done", "You no longer feel weak.");
stringFiles[1976].addEntry("scramjet_downer", "The strength enhancing effects of the Scramjet pass, leaving you feeling weakened.");
stringFiles[1976].addEntry("sedative_h4b_consume", "As you inject the sedative, your sense of feeling deadens.");
stringFiles[1976].addEntry("sedative_h4b_done", "The sedative's aftereffects have faded.");
stringFiles[1976].addEntry("sedative_h4b_downer", "The effects of the sedative fade leaving you intensely sensitive to wounds.");
stringFiles[1976].addEntry("shadowpaw_consume", "You feel an increase in your reaction speed.");
stringFiles[1976].addEntry("shadowpaw_done", "The decrease in your reaction speed seems to have passed.");
stringFiles[1976].addEntry("shadowpaw_downer", "Your reaction speed has slowed considerably.");
stringFiles[1976].addEntry("sweetblossom_consume", "Aches and pains leave your body as the Sweetblossom takes effect.");
stringFiles[1976].addEntry("sweetblossom_done", "The effects of the Sweetblossom have left your system.");
stringFiles[1976].addEntry("sweetblossom_downer", "As the anaesthetic Sweetblossom fades, your wounds suddenly feel sharply more painful.");
stringFiles[1976].addEntry("sys_already_spiced", "You are already under the influence of spice.");
stringFiles[1976].addEntry("thruster_head_consume", "You feel a rush of mental awareness and a massive increase in your mental capabilities.");
stringFiles[1976].addEntry("thruster_head_done", "The intense nausea seems to have left.");
stringFiles[1976].addEntry("thruster_head_downer", "The mind enhancement of the Thruster Head leaves you wracked with nausea.");
stringFiles[1976].addEntry("yarrock_consume", "Lights flash before your eyes as the Yarrock expands your mind.");
stringFiles[1976].addEntry("yarrock_done", "The headache from the Yarrock seems to have gone.");
stringFiles[1976].addEntry("yarrock_downer", "The mind enhance effects of the Yarrock dissipate leaving you with a splitting headache.");

