stringFiles[1980].addEntry("npc_backtowork_6", "");
stringFiles[1980].addEntry("npc_breech_1", "Hah! I am calling to you, friend, if you are arriving here from the Diktat's aide's office, yes!");
stringFiles[1980].addEntry("npc_breech_2", "Hello there! I'm hoping you're from the Diktat's office in Coronet!");
stringFiles[1980].addEntry("npc_breech_3", "Nrrrr-rrr! Hrrrnnnn!");
