stringFiles[1981].addEntry("npc_dropoff_5", "");
stringFiles[1981].addEntry("npc_dropoff_6", "");
stringFiles[1981].addEntry("npc_failure_1", "I regret that you were unable to bring this recording back. I shall endeavor to find another way to acquire this evidence.");
stringFiles[1981].addEntry("npc_failure_2", "Oh no! This is terrible! What will become of Zayna now? I must find a way to help her!");
