stringFiles[1982].addEntry("dontknowyou_1", "Go away! I can't be seen with you!");
stringFiles[1982].addEntry("dontknowyou_2", "Buzz off! I'm busy!");
stringFiles[1982].addEntry("dontknowyou_3", "Go away! Blurga is in the mood to kill!");
