stringFiles[1983] = new StringFile("static_npc/corellia/corran_horn");
stringFiles[1983].addEntry("cantwork", "Working for me can be a bit dangerous. Come back when you've finished what you're doing and we'll talk.");
stringFiles[1983].addEntry("dontknowyou_1", "I'm waiting here to meet somebody else. Good luck to you.");
stringFiles[1983].addEntry("dontknowyou_2", "You're not my contact. You'd better get moving.");
stringFiles[1983].addEntry("dontknowyou_3", "This is not a good place for you to be. Why don't you just go on your way?");
stringFiles[1983].addEntry("dontknowyou_4", "");
stringFiles[1983].addEntry("dontknowyou_5", "");
stringFiles[1983].addEntry("dontknowyou_6", "");
