stringFiles[1983].addEntry("gotowork_6", "");
stringFiles[1983].addEntry("next", "You've been a great help, buddy. Thanks! But I think I need to finish this alone. I'll keep you in mind for future assignments.");
stringFiles[1983].addEntry("notit_1", "");
stringFiles[1983].addEntry("notit_2", "");
stringFiles[1983].addEntry("notit_3", "");
