stringFiles[1984].addEntry("npc_takeme_4", "");
stringFiles[1984].addEntry("npc_takeme_5", "");
stringFiles[1984].addEntry("npc_takeme_6", "");
stringFiles[1984].addEntry("npc_work_1", "I expected you to bring the Lippinoss dossier from the Bothan informant. You do not have it. I am displeased.");
stringFiles[1984].addEntry("npc_work_2", "I expected you to deliver that Lippinoss dossier to her Talz servant. I understand that you haven't yet made the delivery. I am displeased.");
stringFiles[1984].addEntry("npc_work_3", "I expected you to take care of that Trandoshan bounty hunter by now. He may be close. I am very displeased.");
stringFiles[1984].addEntry("npc_work_4", "");
stringFiles[1984].addEntry("npc_work_5", "");
stringFiles[1984].addEntry("npc_work_6", "");
stringFiles[1984].addEntry("otherescort_1", "I am not the person ee-you are looking for.");
stringFiles[1984].addEntry("otherescort_2", "I am waiting for another.");
stringFiles[1984].addEntry("otherescort_3", "You have no business here. Move on.");
stringFiles[1984].addEntry("otherescort_4", "");
stringFiles[1984].addEntry("otherescort_5", "");
stringFiles[1984].addEntry("otherescort_6", "");
