stringFiles[1984].addEntry("return_waypoint_description_1", "Return to Crev Bombaasa with the report.");
stringFiles[1984].addEntry("return_waypoint_description_2", "Return to Crev Bombaasa and let him know the delivery has been completed.");
stringFiles[1984].addEntry("return_waypoint_description_3", "Return to Crev Bombaasa and let him know the bounty hunter is no longer a threat.");
