stringFiles[1992] = new StringFile("static_npc/corellia/gilad_pellaeon");
stringFiles[1992].addEntry("cantwork", "You seem rather preoccupied. Come back when you have some free time.");
stringFiles[1992].addEntry("default", "");
stringFiles[1992].addEntry("dontknowyou_1", "I'm on Imperial business. I can't talk.");
stringFiles[1992].addEntry("dontknowyou_2", "I'm busy and can't talk right now.");
stringFiles[1992].addEntry("dontknowyou_3", "Buzz off, buddy, I'm busy.");
stringFiles[1992].addEntry("dontknowyou_4", "Don't bother me. I'm a very busy man.");
stringFiles[1992].addEntry("dontknowyou_5", "");
stringFiles[1992].addEntry("dontknowyou_6", "");
stringFiles[1992].addEntry("gotowork_1", "Sorry, can't talk now.");
stringFiles[1992].addEntry("gotowork_2", "Sorry, can't talk now.");
