stringFiles[1993].addEntry("npc_failure_5", "");
stringFiles[1993].addEntry("npc_failure_6", "");
stringFiles[1993].addEntry("npc_noloc_1", "Just a moment. Sorry, my commander is calling for a progress report. See me in a few minutes.");
stringFiles[1993].addEntry("npc_noloc_2", "Just a moment. Sorry, my commander is calling for a progress report. See me in a few minutes.");
stringFiles[1993].addEntry("npc_noloc_3", "Just a moment. Sorry, my commander is calling for a progress report. See me in a few minutes.");
