stringFiles[1996] = new StringFile("static_npc/corellia/grondorn_muse");
stringFiles[1996].addEntry("cantwork", "When you're not so busy, would you mind checking back with me?");
stringFiles[1996].addEntry("dontknowyou_1", "I haven't got anything to say to you.");
stringFiles[1996].addEntry("dontknowyou_2", "I'd prefer not to get into a conversation right now.");
