stringFiles[1998] = new StringFile("static_npc/corellia/ignar_ominaz");
stringFiles[1998].addEntry("cantwork", "I can see you asking yourself, Is that really Ignar Ominaz, the swoop racer? Yes indeed, that's me. I have a job for you when you're not busy.");
stringFiles[1998].addEntry("dontknowyou_1", "Sorry, I'm waiting for someone.");
stringFiles[1998].addEntry("dontknowyou_2", "I'm waiting for someone, sorry.");
stringFiles[1998].addEntry("dontknowyou_3", "");
stringFiles[1998].addEntry("dontknowyou_4", "");
