stringFiles[1999].addEntry("cantwork", "Finish your current job and then come se me about some work.");
stringFiles[1999].addEntry("dontknowyou_1", "Why don't you go on about your business?");
stringFiles[1999].addEntry("dontknowyou_2", "I don't have any business with you.");
stringFiles[1999].addEntry("dontknowyou_3", "");
