stringFiles[2000].addEntry("dontknowyou_6", "");
stringFiles[2000].addEntry("gotowork_1", "I expected you to bring a report on something called the Bonadan Contract from Jadam Questrel. Don't you have it?");
stringFiles[2000].addEntry("gotowork_2", "");
