stringFiles[2000].addEntry("gotowork_6", "");
stringFiles[2000].addEntry("next", "I've gotten all the Bonadan Contract witnesses to safety. I don't have anything else right now, but thanks for your earlier help.");
stringFiles[2000].addEntry("notit_1", "I expected you to bring a report on something called the Bonadan Contract from Jadam Questrel. That isn't it.");
stringFiles[2000].addEntry("notit_2", "");
stringFiles[2000].addEntry("notit_3", "");
