stringFiles[2003] = new StringFile("static_npc/corellia/karrek_flim");
stringFiles[2003].addEntry("cantwork", "See me after you've finished your current job.");
stringFiles[2003].addEntry("dontknowyou_1", "I'm waiting here to meet somebody else.");
stringFiles[2003].addEntry("dontknowyou_2", "I can't talk to you right now.");
stringFiles[2003].addEntry("dontknowyou_3", "I'm waiting here to meet someone else. ");
