stringFiles[2005].addEntry("npc_failure_2", "You failed? This will complicate matters. ");
stringFiles[2005].addEntry("npc_failure_3", "Sometimes things don't go like you plan them. Disappointing, but it happens.");
stringFiles[2005].addEntry("npc_failure_4", "");
stringFiles[2005].addEntry("npc_failure_5", "");
stringFiles[2005].addEntry("npc_failure_6", "");
stringFiles[2005].addEntry("npc_noloc_1", "I'm having someone plant a tracer on the courier. They'll contact me once that's done. See me in a while.");
stringFiles[2005].addEntry("npc_noloc_2", "Once we have their location we'll be ready. Can you see me in a while?");
stringFiles[2005].addEntry("npc_noloc_3", "Let me double-check the tracking frequency. Come back in a few minutes.");
