stringFiles[2006].addEntry("gotowork_6", "");
stringFiles[2006].addEntry("next", "I don't have anything more for you now, friend, but keep checking back with me. You never know when business will be booming again.");
stringFiles[2006].addEntry("notit_1", "");
stringFiles[2006].addEntry("notit_2", "These are not the codes I was supposed to get. You're not trying to cheat us, are you?");
stringFiles[2006].addEntry("notit_3", "");
