stringFiles[2007].addEntry("npc_noloc_5", "");
stringFiles[2007].addEntry("npc_noloc_6", "");
stringFiles[2007].addEntry("npc_reset", "If you think you can handle this job later, come back and see me.");
stringFiles[2007].addEntry("npc_reset_1", "If you think you can handle this job later, come back and see me.");
stringFiles[2007].addEntry("npc_reset_2", "If you think you can handle this job later, come back and see me.");
stringFiles[2007].addEntry("npc_reset_3", "If you think you can handle this job later, come back and see me.");
