stringFiles[2008].addEntry("npc_1_5", "");
stringFiles[2008].addEntry("npc_1_6", "");
stringFiles[2008].addEntry("npc_2_1", "Glad to hear it.  Some guy recorded my transaction and he's blackmailing me with it.  I want you to take care of him for me.  Can you do that?");
stringFiles[2008].addEntry("npc_2_2", "");
stringFiles[2008].addEntry("npc_2_3", "");
