stringFiles[2010] = new StringFile("static_npc/corellia/serji_x_arrogantus");
stringFiles[2010].addEntry("cantwork", "I'm a bit busy right now, and by the look of it, so are you. Come back when you get some free time.");
stringFiles[2010].addEntry("dontknowyou_1", "Excuse me, I'm quite busy.");
