stringFiles[2015] = new StringFile("static_npc/corellia/thrackan_sal_solo");
stringFiles[2015].addEntry("cantwork", "You're working for somebody else right now. I won't even think about hiring you if you're working for somebody else.");
stringFiles[2015].addEntry("dontknowyou_1", "I'm sorry, but I'm waiting for somebody else.");
stringFiles[2015].addEntry("dontknowyou_2", "I can't talk to you right now.");
stringFiles[2015].addEntry("dontknowyou_3", "We don't have any business with one another.");
stringFiles[2015].addEntry("dontknowyou_4", "");
stringFiles[2015].addEntry("dontknowyou_5", "");
