stringFiles[2016] = new StringFile("static_npc/corellia/venthan_chassu");
stringFiles[2016].addEntry("cantwork", "I have a mission of compelling importance available to you, once you are not so busy.");
stringFiles[2016].addEntry("dontknowyou_1", "");
stringFiles[2016].addEntry("dontknowyou_2", "I want nothing to do with you.");
stringFiles[2016].addEntry("dontknowyou_3", "");
