stringFiles[2016].addEntry("gotowork_5", "");
stringFiles[2016].addEntry("gotowork_6", "");
stringFiles[2016].addEntry("next", "I have satisfied my yearning for revenge and achieved a certain quietus. I thank you again for your help.");
stringFiles[2016].addEntry("notit_1", "");
stringFiles[2016].addEntry("notit_2", "");
stringFiles[2016].addEntry("notit_3", "");
stringFiles[2016].addEntry("notit_4", "");
