stringFiles[2019].addEntry("return_waypoint_description_1", "Commander Lytus is waiting to question this officer.");
stringFiles[2019].addEntry("return_waypoint_description_2", "Commander Lytus is waiting for you to return");
stringFiles[2019].addEntry("return_waypoint_description_3", "Commander Lytus is waiting for you to return");
stringFiles[2019].addEntry("return_waypoint_description_4", "Commander Lytus is waiting for your return.");
stringFiles[2019].addEntry("return_waypoint_name_1", "Commander Lytus");
stringFiles[2019].addEntry("return_waypoint_name_2", "Commander Lytus");
stringFiles[2019].addEntry("return_waypoint_name_3", "Commander Lytus");
stringFiles[2019].addEntry("return_waypoint_name_4", "Commander Lytus");
