stringFiles[2022].addEntry("player_1_2", "Yes, I will deliver the report.");
stringFiles[2022].addEntry("player_1_3", "Yes, I will help.");
stringFiles[2022].addEntry("player_2_1", "I'd rather not get involved in this sort of thing.");
stringFiles[2022].addEntry("player_2_2", "This is starting to sound like blackmail. I'd rather not.");
stringFiles[2022].addEntry("player_2_3", "This is way too risky. Count me out.");
