stringFiles[2023].addEntry("player_more_3_2", "");
stringFiles[2023].addEntry("player_more_3_3", "");
stringFiles[2023].addEntry("player_reset", "I don't want this mission right now.");
stringFiles[2023].addEntry("player_reset_1", "I don't want this mission right now.");
stringFiles[2023].addEntry("player_reset_2", "I don't want this mission right now.");
stringFiles[2023].addEntry("player_reset_3", "I don't want this mission right now.");
stringFiles[2023].addEntry("player_sorry", "I'll keep working on the mission.");
stringFiles[2023].addEntry("player_sorry_1", "I'll keep working on the mission.");
stringFiles[2023].addEntry("player_sorry_2", "I'll keep working on the mission.");
stringFiles[2023].addEntry("player_sorry_3", "I'll keep working on the mission.");
stringFiles[2023].addEntry("return_waypoint_description_1", "Report your success back to Drakka Judarrl.");
stringFiles[2023].addEntry("return_waypoint_description_2", "Escort the Dantari woman back to Drakka Judarrl.");
stringFiles[2023].addEntry("return_waypoint_description_3", "Report your success back to Drakka Judarrl.");
