stringFiles[2027].addEntry("player_more_3_2", "");
stringFiles[2027].addEntry("player_reset", "I remember who I am now, Baritha. You have no power over me.");
stringFiles[2027].addEntry("player_reset_1", "I remember who I am now, Baritha. You have no power over me.");
stringFiles[2027].addEntry("player_reset_2", "I remember who I am now, Baritha. You have no power over me.");
stringFiles[2027].addEntry("player_reset_3", "I remember who I am now, Baritha. You have no power over me.");
stringFiles[2027].addEntry("player_reset_4", "I remember who I am now, Baritha. You have no power over me.");
stringFiles[2027].addEntry("player_sorry", "Mistress, what do you wish of me?");
stringFiles[2027].addEntry("player_sorry_1", "Mistress, what do you wish of me?");
stringFiles[2027].addEntry("player_sorry_2", "Mistress, what do you wish of me?");
