stringFiles[2031].addEntry("return_waypoint_name_2", "Shaki Hamachil");
stringFiles[2031].addEntry("waypoint_description_1", "Research assistant Shaki Hamachil's superior, scientist Shibb Nisshil, wants the special salts carried from Tibrin to Dathomir by a procurement specialist.");
