stringFiles[2035].addEntry("npc_smuggle_4", "");
stringFiles[2035].addEntry("npc_takeme_1", "I should have known better than to go. But it was too good an offer to turn down.");
stringFiles[2035].addEntry("npc_takeme_2", "");
stringFiles[2035].addEntry("npc_takeme_3", "Take me home.");
stringFiles[2035].addEntry("npc_takeme_4", "");
