stringFiles[2039].addEntry("npc_failure_1", "What? You failed me? HOW DARE YOU!!!");
stringFiles[2039].addEntry("npc_failure_2", "How dare you come back and face me after you have failed. It shall be the slave's collar for you, then.");
stringFiles[2039].addEntry("npc_failure_3", "You were unable to accomplish a simple task as this? Very well... it shall be the slave's collar for you.");
stringFiles[2039].addEntry("npc_failure_4", "How dare you return after you have failed me?");
