stringFiles[2039].addEntry("player_1_1", "Yes, Clan Mother. I shall do so.");
stringFiles[2039].addEntry("player_1_2", "I will not fail you, Mother.");
stringFiles[2039].addEntry("player_1_3", "Yes, Clan Mother, I will do so.");
stringFiles[2039].addEntry("player_1_4", "I shall do so at once, gracious Mother!");
stringFiles[2039].addEntry("player_2_1", "I understand that I'm leaving. Bye!");
stringFiles[2039].addEntry("player_2_2", "I cannot handle them alone. No.");
stringFiles[2039].addEntry("player_2_3", "I will not kill people for a living! No!");
stringFiles[2039].addEntry("player_2_4", "You're too emotional right now. No.");
stringFiles[2039].addEntry("player_3_1", "What do you mean by predecessor?");
stringFiles[2039].addEntry("player_3_2", "If I do so, will I retain my freedom?");
stringFiles[2039].addEntry("player_3_3", "Who shall I dispatch now?");
stringFiles[2039].addEntry("player_3_4", "If I might ask, what troubles you so?");
