stringFiles[2039].addEntry("return_waypoint_description_1", "The Clan Mother awaits your return with the slave's heart");
stringFiles[2039].addEntry("return_waypoint_description_2", "The Clan Mother expects a prompt return");
stringFiles[2039].addEntry("return_waypoint_description_3", "Return and let the Clan Mother know that Augwynne's daughter is dead.");
stringFiles[2039].addEntry("return_waypoint_description_4", "The Nightsister Clan Mother is anxiously waiting to her of Chastina's demise... and to hold that necklace.");
stringFiles[2039].addEntry("return_waypoint_name_1", "Gethzerion");
