stringFiles[2046].addEntry("return_waypoint_description_1", "Charal is waiting for that spleen. Don't keep her waiting.");
stringFiles[2046].addEntry("return_waypoint_description_2", "Charal is waiting for those herbs. Don't keep her waiting.");
stringFiles[2046].addEntry("return_waypoint_description_3", "Charal is waiting for that Ewok's precious salivary glands. Don't keep her waiting.");
stringFiles[2046].addEntry("return_waypoint_description_4", "Return with the commlink and Charal will break your compulsion as your reward.");
stringFiles[2046].addEntry("return_waypoint_name_1", "Charal");
