stringFiles[2047] = new StringFile("static_npc/endor/endor_maraudercitadel_scholar_szingo");
stringFiles[2047].addEntry("cant_work", "You are busy. Come back when you are not.");
stringFiles[2047].addEntry("dontknowyou_1", "Get lost! I'm busy!");
stringFiles[2047].addEntry("dontknowyou_2", "Go! Or we may decide to eat you!");
stringFiles[2047].addEntry("dontknowyou_3", "");
