stringFiles[2047].addEntry("npc_6_3", "");
stringFiles[2047].addEntry("npc_backtowork_1", "Why do you just stand around?");
stringFiles[2047].addEntry("npc_backtowork_2", "There is no time to waste! Hurry and do my bidding!");
stringFiles[2047].addEntry("npc_backtowork_3", "Hurry, before King Terak decides to take out his anger on both our hides!");
stringFiles[2047].addEntry("npc_breech_1", "That's not one of our own! Blast this creature to pieces, lads!");
stringFiles[2047].addEntry("npc_breech_2", "Kill that one! We will feast tonight!");
stringFiles[2047].addEntry("npc_breech_3", "");
stringFiles[2047].addEntry("npc_dropoff_1", "");
stringFiles[2047].addEntry("npc_dropoff_2", "");
stringFiles[2047].addEntry("npc_dropoff_3", "");
stringFiles[2047].addEntry("npc_failure_1", "Those who fail me do not live long. You are lucky I am not King Terak.");
stringFiles[2047].addEntry("npc_failure_2", "How could you have let these fools escape with their lives? You are of no use to me!");
stringFiles[2047].addEntry("npc_failure_3", "I shall blame you for the deaths of King Terak's warriors. Had you killed the beast of many legs this would not have been an issue.");
