stringFiles[2049] = new StringFile("static_npc/endor/endor_moragscastle_morag");
stringFiles[2049].addEntry("cant_work", "There are a thousand creatures in need of killing right now. Finish your current job and hurry back.");
stringFiles[2049].addEntry("dontknowyou_1", "");
stringFiles[2049].addEntry("dontknowyou_2", "");
stringFiles[2049].addEntry("dontknowyou_3", "");
