stringFiles[2050] = new StringFile("static_npc/endor/king_terak");
stringFiles[2050].addEntry("cant_work", "I may have duties for one such as you, but I feel I do not command your full attention. I suggest you abandon your current duties and return at once.");
stringFiles[2050].addEntry("dontknowyou_1", "");
stringFiles[2050].addEntry("dontknowyou_2", "");
stringFiles[2050].addEntry("dontknowyou_3", "");
