stringFiles[2054].addEntry("player_3_1", "What are the documents?");
stringFiles[2054].addEntry("player_3_2", "Won't Imperial patrols be after him if he was shot down?");
stringFiles[2054].addEntry("player_3_3", "How risky is it?");
stringFiles[2054].addEntry("player_3_4", "Have you lost your mind?");
stringFiles[2054].addEntry("player_3_5", "");
