stringFiles[2057].addEntry("player_reset_4", "I don't want this mission right now.");
stringFiles[2057].addEntry("player_reset_5", "I don't want this mission right now.");
stringFiles[2057].addEntry("player_reset_6", "I don't want this mission right now.");
