stringFiles[2059] = new StringFile("static_npc/naboo/boss_nass");
stringFiles[2059].addEntry("cantwork", "Yousa seem mooie mooie busy. Come backo whensa yousa can hep and wesa can mebbe spek.");
stringFiles[2059].addEntry("dontknowyou_1", "I'm afraid I have no time to talk. I need to complete an important mission.");
stringFiles[2059].addEntry("dontknowyou_2", "I can't talk to you now. I'm waiting for a friend.");
stringFiles[2059].addEntry("dontknowyou_3", "Mesa not spek wit yousa. Mesa busy.");
stringFiles[2059].addEntry("dontknowyou_4", "This is Imperial business! Move along!");
