stringFiles[2059].addEntry("gotowork_4", "");
stringFiles[2059].addEntry("gotowork_5", "");
stringFiles[2059].addEntry("gotowork_6", "");
stringFiles[2059].addEntry("next", "Mesa not have maxibig task for yousa. Come backo later.");
stringFiles[2059].addEntry("notit_1", "I don't believe this is what I need.");
stringFiles[2059].addEntry("notit_2", "");
stringFiles[2059].addEntry("notit_3", "");
