stringFiles[2061].addEntry("npc_work_2", "Did you deliver my payment request? I hate to be a bother about this but I am a bit eager to get that money.");
stringFiles[2061].addEntry("npc_work_3", "Did you drop off that application? Please disregard this entire conversation if you had. I can be so pushy sometimes.");
stringFiles[2061].addEntry("npc_work_4", "");
