stringFiles[2066] = new StringFile("static_npc/naboo/gavyn_sykes");
stringFiles[2066].addEntry("cantwork", "I wouldn't ordinarily ask you for help, but I'm in a tight spot. Please check back when you have less to occupy you.");
stringFiles[2066].addEntry("dontknowyou_1", "My dunno yousa. Go 'way!");
stringFiles[2066].addEntry("dontknowyou_2", "");
stringFiles[2066].addEntry("dontknowyou_3", "You got the wrong guy, buddy.");
stringFiles[2066].addEntry("dontknowyou_4", "");
