stringFiles[2068].addEntry("npc_takeme_6", "");
stringFiles[2068].addEntry("npc_work_1", "That plague is ravaging the countryside, and you're lingering here! Would you please rescue Thea Novotin?");
stringFiles[2068].addEntry("npc_work_2", "That plague is ravaging the countryside, and you're lingering here! Would you please pick up those specimens?");
stringFiles[2068].addEntry("npc_work_3", "That plague is ravaging the countryside, and you're lingering here! Would you please deliver that report?");
stringFiles[2068].addEntry("npc_work_4", "Infected carcasses could be on their way to Corellia even now, and you're lingering here! Please stop that poacher!");
stringFiles[2068].addEntry("npc_work_5", "");
stringFiles[2068].addEntry("npc_work_6", "");
