stringFiles[2070].addEntry("player_3_1", "What's this agent's name?");
stringFiles[2070].addEntry("player_3_2", "How did he elude his pursuers?");
stringFiles[2070].addEntry("player_3_3", "Why is this notion ridiculous?");
stringFiles[2070].addEntry("player_3_4", "How did this troubadour gain the Queen's confidence?");
stringFiles[2070].addEntry("player_3_5", "Why must the Gungan leader be silenced?");
stringFiles[2070].addEntry("player_3_6", "Will this get me in trouble with the Royal Security Force?");
stringFiles[2070].addEntry("player_reset_1", "I don't want this mission right now.");
stringFiles[2070].addEntry("player_reset_2", "I don't want this mission right now.");
stringFiles[2070].addEntry("player_reset_3", "I don't want this mission right now.");
