stringFiles[2072].addEntry("player_2_2", "No.");
stringFiles[2072].addEntry("player_2_3", "No.");
stringFiles[2072].addEntry("player_2_4", "No.");
stringFiles[2072].addEntry("player_2_5", "No.");
stringFiles[2072].addEntry("player_2_6", "No.");
stringFiles[2072].addEntry("player_3_1", "What truth are we talking about here exactly?");
stringFiles[2072].addEntry("player_3_2", "What happened exactly?");
stringFiles[2072].addEntry("player_3_3", "Why did the Rebels attack this installation?");
stringFiles[2072].addEntry("player_3_4", "Why did this slicer risk angering an Imperial Inquisitor?");
