stringFiles[2073].addEntry("npc_smuggle_2", "");
stringFiles[2073].addEntry("npc_smuggle_3", "");
stringFiles[2073].addEntry("npc_smuggle_4", "");
stringFiles[2073].addEntry("npc_smuggle_5", "");
stringFiles[2073].addEntry("npc_smuggle_6", "");
