stringFiles[2073].addEntry("npc_takeme_6", "");
stringFiles[2073].addEntry("npc_work_1", "Have you taken out that Gungan informant yet? Dozens of our agents will be compromised if you don't.");
stringFiles[2073].addEntry("npc_work_2", "Have you neutralized that bounty hunter yet? We can't afford him getting any closer to the Senator.");
stringFiles[2073].addEntry("npc_work_3", "Have you gotten rid of that assassin yet? I need to know whether I need to move the Senator or not.");
stringFiles[2073].addEntry("npc_work_4", "");
