stringFiles[2074].addEntry("player_2_3", "No.");
stringFiles[2074].addEntry("player_2_4", "No.");
stringFiles[2074].addEntry("player_2_5", "No.");
stringFiles[2074].addEntry("player_2_6", "No.");
stringFiles[2074].addEntry("player_3_1", "Is it my imagination, or do you not like Borvo?");
stringFiles[2074].addEntry("player_3_2", "Why do you care what the law thinks?");
stringFiles[2074].addEntry("player_3_3", "How am I supposed to fix this?");
stringFiles[2074].addEntry("player_3_4", "What do you think he's involved in?");
stringFiles[2074].addEntry("player_3_5", "What is this bioweapon?");
