stringFiles[2075] = new StringFile("static_npc/naboo/lareen_dantara");
stringFiles[2075].addEntry("cantwork", "Sorry, this is a private family retreat. Can't let you in unless you have an invitation. Funny, you look too busy to enjoy the place.");
stringFiles[2075].addEntry("dontknowyou_1", "");
stringFiles[2075].addEntry("dontknowyou_2", "");
stringFiles[2075].addEntry("dontknowyou_3", "");
stringFiles[2075].addEntry("dontknowyou_4", "");
