stringFiles[2075].addEntry("gotowork_3", "");
stringFiles[2075].addEntry("gotowork_4", "");
stringFiles[2075].addEntry("gotowork_5", "");
stringFiles[2075].addEntry("gotowork_6", "");
stringFiles[2075].addEntry("next", "You again? Well then, I guess I can let you look around some more. Go on in.");
stringFiles[2075].addEntry("notit_1", "");
stringFiles[2075].addEntry("notit_2", "");
stringFiles[2075].addEntry("notit_3", "");
