stringFiles[2078].addEntry("npc_reset_1", "I am sorry to hear you cannot fulfill the assignment. Please consult with me again when you are able.");
stringFiles[2078].addEntry("npc_reset_2", "I am sorry to hear you cannot fulfill the assignment. Please consult with me again when you are able.");
stringFiles[2078].addEntry("npc_reset_3", "I am sorry to hear you cannot fulfill the assignment. Please consult with me again when you are able.");
