stringFiles[2080].addEntry("player_3_1", "What sort of device is it?");
stringFiles[2080].addEntry("player_3_2", "Do I have to bring him back alive?");
stringFiles[2080].addEntry("player_3_3", "What kind of predator?");
stringFiles[2080].addEntry("player_3_4", "Who is this traitor?");
stringFiles[2080].addEntry("player_3_5", "There are Rebels in the palace?");
stringFiles[2080].addEntry("player_3_6", "How did this scientist get to Naboo?");
stringFiles[2080].addEntry("player_reset_1", "I don't want this mission right now.");
