stringFiles[2081] = new StringFile("static_npc/naboo/mullud_bombo");
stringFiles[2081].addEntry("cantwork", "Yousa seem mooie mooie busy. Come backo when yousa have nutten on yousa brain.");
stringFiles[2081].addEntry("dontknowyou_1", "Terribly busy, I'm afraid. Can't talk now.");
stringFiles[2081].addEntry("dontknowyou_2", "");
stringFiles[2081].addEntry("dontknowyou_3", "");
stringFiles[2081].addEntry("dontknowyou_4", "");
stringFiles[2081].addEntry("dontknowyou_5", "");
stringFiles[2081].addEntry("dontknowyou_6", "");
stringFiles[2081].addEntry("gotowork_1", "I was expecting some survey equipment. Was that what you meant to give me?");
stringFiles[2081].addEntry("gotowork_2", "");
stringFiles[2081].addEntry("gotowork_3", "");
stringFiles[2081].addEntry("gotowork_4", "");
stringFiles[2081].addEntry("gotowork_5", "");
stringFiles[2081].addEntry("gotowork_6", "");
stringFiles[2081].addEntry("next", "Mesa no have nutten for yousa to be doin. Mesa busy. Come backo later and mebbe mesa have sumthin.");
stringFiles[2081].addEntry("notit_1", "No, I need some survey equipment. This is definitely not what I ordered. Likely that good-for-nothing Mullud messed everything up. You probably couldn't understand a word he was trying to say.");
stringFiles[2081].addEntry("notit_2", "");
stringFiles[2081].addEntry("notit_3", "");
stringFiles[2081].addEntry("notit_4", "");
stringFiles[2081].addEntry("notit_5", "");
stringFiles[2081].addEntry("notit_6", "");
stringFiles[2081].addEntry("notyet", "Mesa no have nutten for yousa right now.");
stringFiles[2081].addEntry("npc_1_1", "Heyo. Yousa be needin a task? My be needin someone to hep mesa. Yousa no needin to be smarty. Just needin to tek a gizmo to Naboo maxibig patron. Mesa be payen for de hep. Yousa hep mesa?");
stringFiles[2081].addEntry("npc_1_2", "");
stringFiles[2081].addEntry("npc_1_3", "");
stringFiles[2081].addEntry("npc_1_4", "");
stringFiles[2081].addEntry("npc_1_5", "");
