stringFiles[2091] = new StringFile("static_npc/naboo/solcar_dienbel");
stringFiles[2091].addEntry("cantwork", "It wasn't my fault! I was only -- What? You're not with the ISB? Oh. Well, please check with me when you're not busy if you want a job.");
stringFiles[2091].addEntry("dontknowyou_1", "Begone! I am the Emperor, and I brook no interference from underlings!");
stringFiles[2091].addEntry("dontknowyou_2", "Away with you! I am the Emperor, and all must quail before me!");
stringFiles[2091].addEntry("dontknowyou_3", "Off with you, fool! Do you not know your own Emperor? I command you, away!");
stringFiles[2091].addEntry("dontknowyou_4", "");
stringFiles[2091].addEntry("dontknowyou_5", "");
stringFiles[2091].addEntry("dontknowyou_6", "");
