stringFiles[2091].addEntry("gotowork_5", "");
stringFiles[2091].addEntry("gotowork_6", "");
stringFiles[2091].addEntry("next", "I'm preparing a revised mind control technique that I expect will be much more effective. If you know of likely subjects, send them my way.");
stringFiles[2091].addEntry("notit_1", "");
stringFiles[2091].addEntry("notit_2", "");
