stringFiles[2094].addEntry("npc_work_1", "Have you checked on that pilot yet? ");
stringFiles[2094].addEntry("npc_work_2", "Were you going to rescue poor captain Vanool or just leave him to the Gungans?");
stringFiles[2094].addEntry("npc_work_3", "Didn't I give you a mission recently? Something about a Gungan raider hideout?");
stringFiles[2094].addEntry("npc_work_4", "");
stringFiles[2094].addEntry("npc_work_5", "");
stringFiles[2094].addEntry("npc_work_6", "");
