stringFiles[2098].addEntry("player_2_3", "No.");
stringFiles[2098].addEntry("player_2_4", "No.");
stringFiles[2098].addEntry("player_3_1", "What would I have to do?");
stringFiles[2098].addEntry("player_3_2", "Do you know this dispatcher's current whereabouts?");
stringFiles[2098].addEntry("player_3_3", "");
stringFiles[2098].addEntry("player_3_4", "");
stringFiles[2098].addEntry("player_4_1", "What's on the surveillance holo?");
stringFiles[2098].addEntry("player_4_2", "");
