stringFiles[2098].addEntry("player_reset_2", "I don't want this mission right now.");
stringFiles[2098].addEntry("player_reset_3", "I don't want this mission right now.");
stringFiles[2098].addEntry("player_reset_4", "I don't want this mission right now.");
