stringFiles[2098].addEntry("return_waypoint_description_1", "Bring the surveillance holo back to Captain Tarun.");
stringFiles[2098].addEntry("return_waypoint_description_2", "Bring the crooked dispatcher back to Captain Tarun for questioning.");
stringFiles[2098].addEntry("return_waypoint_description_3", "Bring the rescued woman back to Captain Tarun.");
stringFiles[2098].addEntry("return_waypoint_description_4", "Report back to Captain Tarun.");
