stringFiles[2098].addEntry("waypoint_description_1", "Pickup a surveillance holo for Captain Tarun.");
stringFiles[2098].addEntry("waypoint_description_2", "Find and detain the crooked starport dispatcher.");
stringFiles[2098].addEntry("waypoint_description_3", "Rescue an innocent young woman from the clutches of vile gunrunners.");
stringFiles[2098].addEntry("waypoint_description_4", "Take out the leader of the gunrunners.");
