stringFiles[2111].addEntry("player_reset_1", "I don't want this mission right now.");
stringFiles[2111].addEntry("player_reset_2", "I don't want this mission right now.");
stringFiles[2111].addEntry("player_sorry_1", "I'll keep working on the mission.");
stringFiles[2111].addEntry("player_sorry_2", "I'll keep working on the mission.");
stringFiles[2111].addEntry("return_waypoint_description_1", "This Mon Calamari zoologist will reward you for destroying a non-native Corellian gubbur.");
stringFiles[2111].addEntry("return_waypoint_description_2", "This Mon Calamari zoologist will reward you for having destroyed the Talusian guf drolg.");
stringFiles[2111].addEntry("return_waypoint_name_1", "Magur Torigai");
stringFiles[2111].addEntry("return_waypoint_name_2", "Magur Torigai");
stringFiles[2111].addEntry("waypoint_description_1", "Zoologist Magur Torigai would like this non-native amphibian destroyed before it damages the Rori ecosystem.");
stringFiles[2111].addEntry("waypoint_description_2", "Zoologist Magur Torigai would like this Talusian creature destroyed before it damages the Rori ecosystem.");
