stringFiles[2112].addEntry("player_sorry_2", "I'll get back to work.");
stringFiles[2112].addEntry("return_waypoint_description_1", "Bring news of the beast's demise back to Lord Rusper.");
stringFiles[2112].addEntry("return_waypoint_description_2", "Escort the young hunter safely back to Lord Rusper.");
