stringFiles[2116].addEntry("return_waypoint_description_1", "Escort the assistant back to the Selonian Ambassador.");
stringFiles[2116].addEntry("return_waypoint_description_2", "Return to the Selonian Ambassador with the news of your success.");
stringFiles[2116].addEntry("return_waypoint_name_1", "Kathikiis Ruwahurr");
