stringFiles[2117].addEntry("return_waypoint_description_1", "Return to Mourno Draver and inform him that the mission has been completed");
stringFiles[2117].addEntry("return_waypoint_description_2", "Return to Mourno Draver and inform him of your success.");
stringFiles[2117].addEntry("return_waypoint_name_1", "Mourno Draver");
stringFiles[2117].addEntry("return_waypoint_name_2", "Mourno Draver");
