stringFiles[2119].addEntry("player_reset_1", "I don't want this mission right now.");
stringFiles[2119].addEntry("player_reset_2", "I don't want this mission right now.");
stringFiles[2119].addEntry("player_reset_3", "I don't want this mission right now.");
stringFiles[2119].addEntry("player_sorry_1", "I'll keep working on the mission.");
stringFiles[2119].addEntry("player_sorry_2", "I'll keep working on the mission.");
