stringFiles[2119].addEntry("return_waypoint_description_1", "Return to Radlee Mathiss with the datadisc");
stringFiles[2119].addEntry("return_waypoint_description_2", "Return to Radlee Mathiss with the CSA representetive.");
stringFiles[2119].addEntry("return_waypoint_description_3", "Return to Radlee Mathiss and inform him of your success.");
stringFiles[2119].addEntry("return_waypoint_name_1", "Radlee Mathiss");
stringFiles[2119].addEntry("return_waypoint_name_2", "Radlee Mathiss");
