stringFiles[2123].addEntry("return_waypoint_description_1", "Escort the pirate back to Captain Pyne.");
stringFiles[2123].addEntry("return_waypoint_description_2", "Escort the CorSec agent back to headquarters.");
stringFiles[2123].addEntry("return_waypoint_description_3", "Report your success to Captain Pyne.");
