stringFiles[2173].addEntry("player_reset_2", "I don't want to do this anymore.");
stringFiles[2173].addEntry("player_reset_3", "I can't do this.");
stringFiles[2173].addEntry("player_reset_4", "I'm tired of this job.");
stringFiles[2173].addEntry("player_sorry_1", "No, sorry. I'll get on that right away.");
stringFiles[2173].addEntry("player_sorry_2", "I'll get done quick as I can.");
stringFiles[2173].addEntry("player_sorry_3", "This task should be finished soon.");
stringFiles[2173].addEntry("player_sorry_4", "I just need a little more time...");
stringFiles[2173].addEntry("return_waypoint_description_1", "Mining outpost foreman.");
stringFiles[2173].addEntry("return_waypoint_description_2", "Mining outpost foreman.");
stringFiles[2173].addEntry("return_waypoint_description_3", "Mining outpost foreman.");
stringFiles[2173].addEntry("return_waypoint_name_1", "Jazeen Thumm");
stringFiles[2173].addEntry("return_waypoint_name_2", "Jazeen Thumm");
stringFiles[2173].addEntry("return_waypoint_name_3", "Jazeen Thumm");
stringFiles[2173].addEntry("waypoint_description_1", "This is the location of a survey site in need of repair parts for a mineral scanner.");
stringFiles[2173].addEntry("waypoint_description_2", "A group of anglers who have recently been preying on the mining outpost.");
stringFiles[2173].addEntry("waypoint_description_3", "The survivors of a survey team beset by a pack of ravenous choku.");
stringFiles[2173].addEntry("waypoint_name_1", "Survey Site");
