stringFiles[2174].addEntry("player_2_2", "No");
stringFiles[2174].addEntry("player_2_3", "No");
stringFiles[2174].addEntry("player_3_1", "How do you want me to shake things up?");
stringFiles[2174].addEntry("player_3_2", "A surprise, eh? The kind that involves a lot of collateral damage?");
stringFiles[2174].addEntry("player_3_3", "Why are you so sure there's a mobile base?");
