stringFiles[2175] = new StringFile("static_npc/yavin/yavin_massassi_cx-425");
stringFiles[2175].addEntry("cant_work", "Report here after you've completed your current assignment.");
stringFiles[2175].addEntry("dontknowyou_1", "You're in the wrong place, friend. No supplies available today.");
stringFiles[2175].addEntry("dontknowyou_2", "");
stringFiles[2175].addEntry("gotowork_1", "");
stringFiles[2175].addEntry("gotowork_2", "");
stringFiles[2175].addEntry("next", "No assignments today.");
stringFiles[2175].addEntry("notit_1", "");
stringFiles[2175].addEntry("notit_2", "");
stringFiles[2175].addEntry("notyet", "I can't speak with you right now, I'm on duty.");
stringFiles[2175].addEntry("npc_1_1", "Medics at an independent supply depot were seen to issue supplies to a known Rebel. We want you to blow up the depot.");
stringFiles[2175].addEntry("npc_1_2", "We've located a Rebel transmission relay. Seems to be hidden in a lair of klikniks, some kind of native bugs. Destroy the lair and that should take out the transmitter.");
stringFiles[2175].addEntry("npc_2_1", "Report back here when the depot is gone.");
stringFiles[2175].addEntry("npc_2_2", "Right. Report back when you've destroyed the bug lair.");
stringFiles[2175].addEntry("npc_3_1", "Very well, that's all.");
stringFiles[2175].addEntry("npc_3_2", "Don't want to crush a few bugs? Well, check back if you change your mind.");
stringFiles[2175].addEntry("npc_4_1", "They're probably all Rebel sympathizers, so they deserve to die. Do you want the job or not?");
stringFiles[2175].addEntry("npc_4_2", "Saves time. Bugs are bugs. Do you want the job or not?");
stringFiles[2175].addEntry("npc_5_1", "");
stringFiles[2175].addEntry("npc_5_2", "");
stringFiles[2175].addEntry("npc_6_1", "");
stringFiles[2175].addEntry("npc_6_2", "");
stringFiles[2175].addEntry("npc_backtowork_1", "That's all the info I have. Destroy the medical supply depot.");
stringFiles[2175].addEntry("npc_backtowork_2", "That's all the information I have. Destroy the kliknik lair.");
stringFiles[2175].addEntry("npc_breech_1", "Imperial! Attack!");
