stringFiles[2175].addEntry("npc_noloc_2", "I'm waiting on coordinates for the kliknik lair. Check with me in a few moments.");
stringFiles[2175].addEntry("npc_reset_1", "No stomach for facing a medical supply depot? Not much of a soldier.");
stringFiles[2175].addEntry("npc_reset_2", "No stomach for facing a medical supply depot? Not much of a soldier.");
stringFiles[2175].addEntry("npc_reward_1", "Good. Report back if you want another assignment.");
stringFiles[2175].addEntry("npc_reward_2", "Good job. That's all for now.");
