stringFiles[2175].addEntry("return_waypoint_name_2", "CX-425");
stringFiles[2175].addEntry("waypoint_description_1", "Stormtrooper sergeant CX-425 wants this independent depot blown up because it provided supplies to a Rebel.");
stringFiles[2175].addEntry("waypoint_description_2", "Stormtrooper sergeant CX-425 believes this lair of klikniks harbors a hidden Rebel transmitter.");
