stringFiles[2176].addEntry("npc_takeme_2", "");
stringFiles[2176].addEntry("npc_takeme_3", "");
stringFiles[2176].addEntry("npc_work_1", "I expect you to attack those stranded Rebels and bring back their leader's weapon. Get moving!");
stringFiles[2176].addEntry("npc_work_2", "I have heard no report of the Rebel Special Forces squad dying in battle. Why not?");
stringFiles[2176].addEntry("npc_work_3", "Is something holding you back from destroying that Rebel weapons lab? Something more important than the end of the Civil War?");
stringFiles[2176].addEntry("otherescort_1", "");
stringFiles[2176].addEntry("otherescort_2", "");
stringFiles[2176].addEntry("otherescort_3", "");
stringFiles[2176].addEntry("player_1_1", "Yes.");
stringFiles[2176].addEntry("player_1_2", "Yes.");
stringFiles[2176].addEntry("player_1_3", "Yes.");
stringFiles[2176].addEntry("player_2_1", "No.");
stringFiles[2176].addEntry("player_2_2", "No.");
stringFiles[2176].addEntry("player_2_3", "No.");
stringFiles[2176].addEntry("player_3_1", "Why do you think the Rebels have a secret weapon?");
stringFiles[2176].addEntry("player_3_2", "Why do you think this Special Forces squad is carrying the secret weapon?");
stringFiles[2176].addEntry("player_3_3", "After all this time, you still think the Rebels have a secret weapon?");
