stringFiles[2179].addEntry("npc_noloc_1", "One moment while I verify those coordinates.");
stringFiles[2179].addEntry("npc_noloc_2", "We need to verify the lieutenant's current position. Could you check back with me in a few moments?");
stringFiles[2179].addEntry("npc_noloc_3", "I need to verify the depot's location with our scouts. Check back in a few moments.");
stringFiles[2179].addEntry("npc_reset_1", "Fine. Come back later if you think you can finish this out.");
stringFiles[2179].addEntry("npc_reset_2", "Fine. Come back later if you think you can finish this out.");
stringFiles[2179].addEntry("npc_reset_3", "Fine. Come back later if you think you can finish this out.");
stringFiles[2179].addEntry("npc_reward_1", "Well done. Your efforts will make our work here much easier. Report back if you haven't gotten your fill of killing Imperials.");
stringFiles[2179].addEntry("npc_reward_2", "Good job. Cut off the head and the body cannot survive. Enjoy your reward.");
stringFiles[2179].addEntry("npc_reward_3", "Now that was a job well done. I think our people will be able to take a breather. You're an inspiration to us all.");
stringFiles[2179].addEntry("npc_smuggle_1", "");
stringFiles[2179].addEntry("npc_smuggle_2", "");
stringFiles[2179].addEntry("npc_smuggle_3", "");
