stringFiles[2217].addEntry("npc_failure_1", "You have failed me. You are fortunate that I am more forgiving than my master.");
stringFiles[2217].addEntry("npc_failure_2", "You have failed me for the last time, Agent.");
stringFiles[2217].addEntry("npc_failure_3", "You were given a direct order, yet you failed me. The justice of the Emperor prevents me from destroying you right now.");
stringFiles[2217].addEntry("npc_failure_4", "You have failed me for the last time, Agent.");
