stringFiles[2217].addEntry("player_1_1", "Yes, Lord Vader.");
stringFiles[2217].addEntry("player_1_2", "I shall do so at once, Lord Vader.");
stringFiles[2217].addEntry("player_1_3", "As you wish, Lord Vader.");
stringFiles[2217].addEntry("player_1_4", "Yes, Lord Vader. What will you need of me?");
