stringFiles[2217].addEntry("player_2_4", "I cannot do this, Lord Vader.");
stringFiles[2217].addEntry("player_2_5", "I will not do so, Vader.");
stringFiles[2217].addEntry("player_2_6", "I will not destroy a family for the Empire.");
