stringFiles[2217].addEntry("return_waypoint_description_1", "Lord Vader is awaiting your return. Bring him the datapad to complete your mission.");
stringFiles[2217].addEntry("return_waypoint_description_2", "Lord Vader is waiting for you to bring those documents back to him.");
stringFiles[2217].addEntry("return_waypoint_description_3", "Now that you have the letter, return it to Lord Vader immediately.");
stringFiles[2217].addEntry("return_waypoint_description_4", "Darth Vader is waiting for this information. Return to him at once.");
stringFiles[2217].addEntry("return_waypoint_description_5", "Return to Vader to inform him that the deed is done.");
stringFiles[2217].addEntry("return_waypoint_description_6", "Return to Lord Vader now that the Kenobi line has been destroyed.");
