stringFiles[2218].addEntry("npc_reset", "You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?");
stringFiles[2218].addEntry("npc_reset_1", "You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?");
stringFiles[2218].addEntry("npc_reset_2", "You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?");
stringFiles[2218].addEntry("npc_reset_3", "You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?");
stringFiles[2218].addEntry("npc_reset_4", "You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?");
stringFiles[2218].addEntry("npc_reset_5", "You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?");
