stringFiles[2218].addEntry("return_waypoint_description_1", "Bring the thug to the Emperor. Safely.");
stringFiles[2218].addEntry("return_waypoint_description_2", "Emperor Palpatine has commanded you to return when you are done.");
stringFiles[2218].addEntry("return_waypoint_description_3", "You are expected to give a report to the Emperor");
stringFiles[2218].addEntry("return_waypoint_description_4", "Return with the handmaiden. The Emperor expects from you a prompt return.");
stringFiles[2218].addEntry("return_waypoint_description_5", "Return to the Emperor now that you have killed all the witnesses.");
stringFiles[2218].addEntry("return_waypoint_description_6", "Return to the Emperor to give him the good news.");
stringFiles[2218].addEntry("return_waypoint_description_7", "Return to the Emperor now to see his plan come to completion.");
