stringFiles[2219].addEntry("npc_breech_1", "Hello!  Are you here for me?");
stringFiles[2219].addEntry("npc_breech_2", "Sorry, but you're in the way. I guess I'll charge them for you too.");
stringFiles[2219].addEntry("npc_breech_3", "Sorry, but you're in the way. I guess I'll charge them for you too.");
stringFiles[2219].addEntry("npc_breech_4", "We knew the Empire would retaliate for us killing the Moff! You'll die too!");
stringFiles[2219].addEntry("npc_breech_5", "Zzzrtzz! In the name of the Empire, identify - zzzrtzzz-  In the name of - zzzrtzzz..");
stringFiles[2219].addEntry("npc_dropoff_1", "I will inform the chamberlain that you performed your duty to the tee.");
stringFiles[2219].addEntry("npc_dropoff_2", "");
