stringFiles[2259] = new StringFile("tt8l");
stringFiles[2259].addEntry("tt8l1", "State your business.");
stringFiles[2259].addEntry("tt8l10", "Who are you?");
stringFiles[2259].addEntry("tt8l11", "Jabba does not mingle with tourists. Perform errands for Jabba and he may grant you audience.");
stringFiles[2259].addEntry("tt8l12", "Wait here. I will inquire if anyone inside needs any minor tasks done by the likes of one such as yourself.");
stringFiles[2259].addEntry("tt8l13", "This is the Palace of Jabba the Hutt.  It is not open to the public. If you wish to enter, you must first complete tasks for Jabba and his associates.");
stringFiles[2259].addEntry("tt8l14", "I am TT-8L. If you wish audience with Jabba the Hutt, I can ask inside the palace if anyone has work for you.");
stringFiles[2259].addEntry("tt8l15", "Yes. Give me a task.");
stringFiles[2259].addEntry("tt8l16", "No. I am not ready, yet.");
stringFiles[2259].addEntry("tt8l17", "Your task is as follows.");
stringFiles[2259].addEntry("tt8l18", "Return when you are ready to serve Jabba.");
stringFiles[2259].addEntry("tt8l2", "There is more work to be done. Are you ready for another mission?");
stringFiles[2259].addEntry("tt8l3", "Welcome back.");
stringFiles[2259].addEntry("tt8l4", "Your kind is not welcome here.");
stringFiles[2259].addEntry("tt8l5", "There are no appointments currently scheduled with Imperials. Go away.");
stringFiles[2259].addEntry("tt8l6", "Bib Fortuna will speak with you now. Go find him inside.");
stringFiles[2259].addEntry("tt8l7", "I want to see Jabba the Hutt.");
stringFiles[2259].addEntry("tt8l8", "I am here to offer my services.");
stringFiles[2259].addEntry("tt8l9", "What is this place?");

